#' Extract NEON Soil-related observations for soil parameter calibration for single site
#'
#' Extracts soil temperature, soil moisture, and soil respiration observations
#' for a single NEON site from the processed NEON data generated by John
#' Zobitz. The requested model site index is matched to a NEON site using the
#' supplied lookup table.
#'
#' Only monthly files overlapping the requested date range are read. Soil
#' temperature and soil moisture observations are retained separately for all
#' available vertical positions. For each vertical position and timestamp,
#' measurements from multiple horizontal positions are first averaged spatially
#' and are then aggregated to exact 3-hour UTC intervals.
#'
#' Soil respiration is read from the processed soil CO2 flux files. Both the
#' Marshall and Millington-Quirk estimates are retained. Soil respiration is
#' first averaged across horizontal positions and then aggregated to 3-hour UTC
#' intervals.
#'
#' The function writes separate CSV files for soil temperature, soil moisture,
#' soil respiration, and the available soil-depth summary. It also saves an
#' uncompressed RDS file containing all extracted data for faster subsequent
#' access.
#'
#' @md
#' @param lookup A data.frame or data.table containing the mapping between model
#'   site indices and NEON sites. Must contain `index` and `NEON_code`.
#'   `AmeriFlux_ID` and `NEON_name` are retained as metadata when available.
#' @param index Integer model site index used to identify the corresponding
#'   NEON site in `lookup`.
#' @param start_date Character string giving the first date to extract in
#'   `"YYYY-MM-DD"` format. The start date is inclusive.
#' @param end_date Character string giving the last date to extract in
#'   `"YYYY-MM-DD"` format. The end date is inclusive.
#' @param output_dir Directory where extracted CSV and RDS files will be saved.
#'   The directory is created if it does not already exist.
#' @param env_dir Directory containing John Zobitz's processed NEON
#'   environmental files (`env-meas-<SITE>-<YYYY-MM>.Rda`). These files are used
#'   to extract soil temperature and volumetric soil water content.
#' @param flux_dir Directory containing John Zobitz's processed NEON soil CO2
#'   flux files (`out-flux-<SITE>-<YYYY-MM>.Rda`). These files are used to
#'   extract Marshall and Millington-Quirk soil respiration estimates.
#'
#' @return A list containing:
#'   * `metadata`: site identifiers, requested dates, and numbers of files read.
#'   * `soilT`: 3-hour soil temperature observations for all available vertical
#'     positions.
#'   * `soilMoisture`: 3-hour volumetric soil water content observations for all
#'     available vertical positions.
#'   * `soilRespiration`: 3-hour Marshall and Millington-Quirk soil respiration
#'     estimates.
#'   * `depth_summary`: available vertical positions, mean depth offsets, and
#'     temporal coverage for soil temperature and soil moisture.
#'
#' @export
#' @author Yang Gu
get_soil_neon_data_single_site <- function(
    lookup,
    index,
    start_date,
    end_date,
    output_dir,
    env_dir =
      "/projectnb/dietzelab/jzobitz/02-NEON-sites/env-data",
    flux_dir =
      "/projectnb/dietzelab/jzobitz/02-NEON-sites/flux-results"
) {
  # ==========================================================
  # 0. Load / check
  # ==========================================================
  
  lookup_dt <- as.data.table(
    copy(lookup)
  )
  
  
  required_lookup_cols <- c(
    "index",
    "NEON_code"
  )
  
  
  if (
    !all(
      required_lookup_cols %in%
      names(lookup_dt)
    )
  ) {
    
    stop(
      "lookup must contain: ",
      paste(
        required_lookup_cols,
        collapse = ", "
      )
    )
  }
  
  
  site_index <- as.integer(
    index
  )
  
  
  if (
    length(site_index) != 1L ||
    !is.finite(site_index)
  ) {
    
    stop(
      "`index` must be one numeric site index."
    )
  }
  
  
  # ==========================================================
  # 1. Resolve index -> NEON site
  # ==========================================================
  
  site_row <- unique(
    lookup_dt[
      index == site_index &
        !is.na(NEON_code) &
        NEON_code != ""
    ]
  )
  
  
  if (nrow(site_row) == 0L) {
    
    stop(
      "Index ",
      site_index,
      " has no NEON_code in lookup."
    )
  }
  
  
  neon_codes <- unique(
    site_row$NEON_code
  )
  
  
  neon_codes <- neon_codes[
    !is.na(neon_codes) &
      neon_codes != ""
  ]
  
  
  if (length(neon_codes) != 1L) {
    
    stop(
      "Index ",
      site_index,
      " does not map uniquely to one NEON site."
    )
  }
  
  
  neon_code <- as.character(
    neon_codes[1]
  )
  
  
  neon_name <- if (
    "NEON_name" %in% names(site_row)
  ) {
    
    unique(
      site_row$NEON_name
    )[1]
    
  } else {
    
    NA_character_
  }
  
  
  ameriflux_id <- if (
    "AmeriFlux_ID" %in% names(site_row)
  ) {
    
    unique(
      site_row$AmeriFlux_ID
    )[1]
    
  } else {
    
    NA_character_
  }
  
  
  cat(
    "\n============================================\n",
    "NEON CALIBRATION DATA\n",
    "============================================\n",
    "Index:       ", site_index, "\n",
    "NEON code:   ", neon_code, "\n",
    "NEON name:   ", neon_name, "\n",
    "AmeriFlux:   ", ameriflux_id, "\n",
    "Start date:  ", start_date, "\n",
    "End date:    ", end_date, "\n",
    "============================================\n\n",
    sep = ""
  )
  
  
  # ==========================================================
  # 2. Requested time range
  # ==========================================================
  
  start_time <- as.POSIXct(
    paste0(
      start_date,
      " 00:00:00"
    ),
    tz = "UTC"
  )
  
  
  # Inclusive end date
  end_time <- as.POSIXct(
    paste0(
      end_date,
      " 00:00:00"
    ),
    tz = "UTC"
  ) + 86400
  
  
  if (
    is.na(start_time) ||
    is.na(end_time)
  ) {
    
    stop(
      "Dates must use YYYY-MM-DD."
    )
  }
  
  
  if (end_time <= start_time) {
    
    stop(
      "end_date must be >= start_date."
    )
  }
  
  
  # ==========================================================
  # 3. Months that actually need to be read
  # ==========================================================
  
  first_month <- as.Date(
    format(
      start_time,
      "%Y-%m-01",
      tz = "UTC"
    )
  )
  
  
  last_month <- as.Date(
    format(
      end_time - 1,
      "%Y-%m-01",
      tz = "UTC"
    )
  )
  
  
  months <- seq(
    first_month,
    last_month,
    by = "month"
  )
  
  
  month_tags <- format(
    months,
    "%Y-%m"
  )
  
  
  # ==========================================================
  # Helper:
  # construct monthly file paths DIRECTLY
  #
  # This is faster than scanning the whole John directory.
  # ==========================================================
  
  find_monthly_files <- function(
    directory,
    prefix
  ) {
    
    files <- character()
    
    
    for (month_i in month_tags) {
      
      candidates <- c(
        
        file.path(
          directory,
          paste0(
            prefix,
            neon_code,
            "-",
            month_i,
            ".Rda"
          )
        ),
        
        file.path(
          directory,
          paste0(
            prefix,
            neon_code,
            "-",
            month_i,
            ".RData"
          )
        )
      )
      
      
      existing <- candidates[
        file.exists(
          candidates
        )
      ]
      
      
      if (length(existing) > 0L) {
        
        # Prefer first match (.Rda)
        files <- c(
          files,
          existing[1]
        )
      }
    }
    
    
    unique(files)
  }
  
  
  # ==========================================================
  # 4. Helpers
  # ==========================================================
  
  mean_finite <- function(x) {
    
    x <- suppressWarnings(
      as.numeric(x)
    )
    
    x <- x[
      is.finite(x)
    ]
    
    
    if (length(x) == 0L) {
      return(NA_real_)
    }
    
    
    mean(x)
  }
  
  
  sd_finite <- function(x) {
    
    x <- suppressWarnings(
      as.numeric(x)
    )
    
    x <- x[
      is.finite(x)
    ]
    
    
    if (length(x) <= 1L) {
      return(NA_real_)
    }
    
    
    sd(x)
  }
  
  
  floor_3hour <- function(time) {
    
    as.POSIXct(
      floor(
        as.numeric(time) /
          10800
      ) *
        10800,
      
      origin =
        "1970-01-01",
      
      tz =
        "UTC"
    )
  }
  
  
  # ==========================================================
  # Generic reader for NEON sensor observations
  #
  # Keeps:
  #   every verticalPosition separately
  #
  # Averages:
  #   horizontalPosition first
  #
  # Then:
  #   30 min -> 3 hour
  # ==========================================================
  
  aggregate_neon_sensor <- function(
    raw_data,
    value_col,
    output_name
  ) {
    
    
    if (
      is.null(raw_data) ||
      nrow(raw_data) == 0L
    ) {
      
      return(NULL)
    }
    
    
    dt <- as.data.table(
      copy(raw_data)
    )
    
    
    required_cols <- c(
      "startDateTime",
      "horizontalPosition",
      "verticalPosition",
      value_col
    )
    
    
    if (
      !all(
        required_cols %in%
        names(dt)
      )
    ) {
      
      return(NULL)
    }
    
    
    keep_cols <- intersect(
      c(
        "startDateTime",
        "horizontalPosition",
        "verticalPosition",
        "zOffset",
        value_col
      ),
      names(dt)
    )
    
    
    dt <- dt[
      ,
      ..keep_cols
    ]
    
    
    # If no zOffset exists, create placeholder
    if (
      !"zOffset" %in%
      names(dt)
    ) {
      
      dt[
        ,
        zOffset := NA_real_
      ]
    }
    
    
    dt[
      ,
      time :=
        as.POSIXct(
          startDateTime,
          tz = "UTC"
        )
    ]
    
    
    dt[
      ,
      horizontalPosition :=
        as.character(
          horizontalPosition
        )
    ]
    
    
    dt[
      ,
      verticalPosition :=
        as.character(
          verticalPosition
        )
    ]
    
    
    dt[
      ,
      value :=
        suppressWarnings(
          as.numeric(
            get(
              value_col
            )
          )
        )
    ]
    
    
    # --------------------------------------------------------
    # Filter date range immediately
    # --------------------------------------------------------
    
    dt <- dt[
      time >= start_time &
        time < end_time &
        !is.na(time) &
        !is.na(verticalPosition) &
        verticalPosition != "" &
        is.finite(value)
    ]
    
    
    if (nrow(dt) == 0L) {
      
      return(NULL)
    }
    
    
    # ========================================================
    # First:
    # average HORIZONTAL positions
    #
    # Never average verticalPosition here.
    # ========================================================
    
    dt_30min <- dt[
      ,
      .(
        
        value =
          mean(
            value,
            na.rm = TRUE
          ),
        
        spatial_sd =
          if (.N > 1L) {
            
            sd(
              value,
              na.rm = TRUE
            )
            
          } else {
            
            NA_real_
          },
        
        mean_zOffset =
          mean_finite(
            zOffset
          ),
        
        n_position =
          uniqueN(
            horizontalPosition
          )
      ),
      
      by = .(
        time,
        verticalPosition
      )
    ]
    
    
    # ========================================================
    # Exact 3-hour UTC bin
    # ========================================================
    
    dt_30min[
      ,
      time_3h :=
        floor_3hour(
          time
        )
    ]
    
    
    # ========================================================
    # 30-min -> 3-hour
    #
    # STILL keep every depth independently.
    # ========================================================
    
    out <- dt_30min[
      ,
      .(
        
        value =
          mean(
            value,
            na.rm = TRUE
          ),
        
        temporal_sd =
          if (.N > 1L) {
            
            sd(
              value,
              na.rm = TRUE
            )
            
          } else {
            
            NA_real_
          },
        
        mean_spatial_sd =
          mean_finite(
            spatial_sd
          ),
        
        mean_zOffset =
          mean_finite(
            mean_zOffset
          ),
        
        n_30min =
          .N,
        
        mean_n_position =
          mean(
            n_position,
            na.rm = TRUE
          )
      ),
      
      by = .(
        time = time_3h,
        verticalPosition
      )
    ]
    
    
    setnames(
      out,
      
      old = c(
        "value",
        "temporal_sd",
        "mean_spatial_sd"
      ),
      
      new = c(
        output_name,
        
        paste0(
          output_name,
          "_temporal_sd"
        ),
        
        paste0(
          output_name,
          "_spatial_sd"
        )
      )
    )
    
    
    return(
      out
    )
  }
  
  
  # ==========================================================
  # 5. ENV DATA
  #
  # Soil Moisture:
  #   site_data[[2]][[2]]
  #
  # Soil Temperature:
  #   site_data[[2]][[3]]
  #
  # IMPORTANT:
  # One env file is loaded ONCE,
  # then both variables are extracted.
  # ==========================================================
  
  env_files <- find_monthly_files(
    directory =
      env_dir,
    
    prefix =
      "env-meas-"
  )
  
  
  cat(
    "ENV monthly files found:",
    length(env_files),
    "\n"
  )
  
  
  read_one_env_file <- function(f) {
    
    e <- new.env()
    
    
    ok <- tryCatch(
      {
        
        load(
          f,
          envir = e
        )
        
        TRUE
      },
      
      error = function(err) {
        
        FALSE
      }
    )
    
    
    if (!ok) {
      return(NULL)
    }
    
    
    if (
      !exists(
        "site_data",
        envir = e,
        inherits = FALSE
      )
    ) {
      
      return(NULL)
    }
    
    
    site_data <- get(
      "site_data",
      envir = e,
      inherits = FALSE
    )
    
    
    # --------------------------------------------------------
    # Soil moisture
    # --------------------------------------------------------
    
    soil_m_raw <- tryCatch(
      
      as.data.table(
        site_data[[2]][[2]]
      ),
      
      error = function(e) {
        NULL
      }
    )
    
    
    soil_m <- aggregate_neon_sensor(
      
      raw_data =
        soil_m_raw,
      
      value_col =
        "VSWCMean",
      
      output_name =
        "VSWC"
    )
    
    
    # --------------------------------------------------------
    # Soil temperature
    # --------------------------------------------------------
    
    soil_t_raw <- tryCatch(
      
      as.data.table(
        site_data[[2]][[3]]
      ),
      
      error = function(e) {
        NULL
      }
    )
    
    
    soil_t <- aggregate_neon_sensor(
      
      raw_data =
        soil_t_raw,
      
      value_col =
        "soilTempMean",
      
      output_name =
        "SoilT"
    )
    
    
    list(
      soilT =
        soil_t,
      
      soilMoisture =
        soil_m
    )
  }
  
  
  # ==========================================================
  # Load all requested ENV months
  # ==========================================================
  
  t0 <- Sys.time()
  
  
  env_results <- lapply(
    env_files,
    read_one_env_file
  )
  
  
  env_results <- Filter(
    Negate(is.null),
    env_results
  )
  
  
  # ==========================================================
  # Soil T
  # ==========================================================
  
  soilT_list <- Filter(
    
    Negate(is.null),
    
    lapply(
      env_results,
      `[[`,
      "soilT"
    )
  )
  
  
  if (length(soilT_list) > 0L) {
    
    soilT <- rbindlist(
      soilT_list,
      use.names = TRUE,
      fill = TRUE
    )
    
    
    # Possible month-boundary duplicate
    soilT <- soilT[
      ,
      .(
        
        SoilT =
          mean(
            SoilT,
            na.rm = TRUE
          ),
        
        SoilT_temporal_sd =
          mean_finite(
            SoilT_temporal_sd
          ),
        
        SoilT_spatial_sd =
          mean_finite(
            SoilT_spatial_sd
          ),
        
        mean_zOffset =
          mean_finite(
            mean_zOffset
          ),
        
        n_30min =
          max(
            n_30min,
            na.rm = TRUE
          ),
        
        mean_n_position =
          mean(
            mean_n_position,
            na.rm = TRUE
          )
      ),
      
      by = .(
        time,
        verticalPosition
      )
    ]
    
    
  } else {
    
    soilT <- data.table()
  }
  
  
  # ==========================================================
  # Soil Moisture
  # ==========================================================
  
  soilM_list <- Filter(
    
    Negate(is.null),
    
    lapply(
      env_results,
      `[[`,
      "soilMoisture"
    )
  )
  
  
  if (length(soilM_list) > 0L) {
    
    soilMoisture <- rbindlist(
      soilM_list,
      use.names = TRUE,
      fill = TRUE
    )
    
    
    soilMoisture <- soilMoisture[
      ,
      .(
        
        VSWC =
          mean(
            VSWC,
            na.rm = TRUE
          ),
        
        VSWC_temporal_sd =
          mean_finite(
            VSWC_temporal_sd
          ),
        
        VSWC_spatial_sd =
          mean_finite(
            VSWC_spatial_sd
          ),
        
        mean_zOffset =
          mean_finite(
            mean_zOffset
          ),
        
        n_30min =
          max(
            n_30min,
            na.rm = TRUE
          ),
        
        mean_n_position =
          mean(
            mean_n_position,
            na.rm = TRUE
          )
      ),
      
      by = .(
        time,
        verticalPosition
      )
    ]
    
    
  } else {
    
    soilMoisture <- data.table()
  }
  
  
  rm(
    env_results,
    soilT_list,
    soilM_list
  )
  
  
  gc()
  
  
  # ==========================================================
  # 6. SOIL RESPIRATION
  #
  # John's out_fluxes:
  #
  # row 4 = Marshall
  # row 8 = Millington-Quirk
  # ==========================================================
  
  flux_files <- find_monthly_files(
    
    directory =
      flux_dir,
    
    prefix =
      "out-flux-"
  )
  
  
  cat(
    "SoilResp monthly files found:",
    length(flux_files),
    "\n"
  )
  
  
  get_flux <- function(
    x,
    row_number
  ) {
    
    
    if (
      is.null(x) ||
      nrow(x) < row_number ||
      !"flux" %in% names(x)
    ) {
      
      return(NA_real_)
    }
    
    
    value <- suppressWarnings(
      as.numeric(
        x$flux[
          row_number
        ]
      )
    )
    
    
    if (
      length(value) != 1L ||
      !is.finite(value)
    ) {
      
      return(NA_real_)
    }
    
    
    return(
      value
    )
  }
  
  
  read_one_flux_file <- function(f) {
    
    e <- new.env()
    
    
    ok <- tryCatch(
      {
        
        load(
          f,
          envir = e
        )
        
        TRUE
      },
      
      error = function(err) {
        
        FALSE
      }
    )
    
    
    if (!ok) {
      return(NULL)
    }
    
    
    if (
      !exists(
        "out_fluxes",
        envir = e,
        inherits = FALSE
      )
    ) {
      
      return(NULL)
    }
    
    
    x <- get(
      "out_fluxes",
      envir = e,
      inherits = FALSE
    )
    
    
    if (
      nrow(x) == 0L ||
      ncol(x) < 3L
    ) {
      
      return(NULL)
    }
    
    
    flux_compute <- x[[3]]
    
    
    # --------------------------------------------------------
    # Marshall = row 4
    # --------------------------------------------------------
    
    marshall <- vapply(
      
      flux_compute,
      
      function(z) {
        get_flux(
          z,
          4L
        )
      },
      
      numeric(1)
    )
    
    
    # --------------------------------------------------------
    # Millington-Quirk = row 8
    # --------------------------------------------------------
    
    mq <- vapply(
      
      flux_compute,
      
      function(z) {
        get_flux(
          z,
          8L
        )
      },
      
      numeric(1)
    )
    
    
    dt <- data.table(
      
      time =
        as.POSIXct(
          x$startDateTime,
          tz = "UTC"
        ),
      
      horizontalPosition =
        as.character(
          x$horizontalPosition
        ),
      
      Marshall =
        marshall,
      
      Millington_Quirk =
        mq
    )
    
    
    # Date filter immediately
    dt <- dt[
      time >= start_time &
        time < end_time &
        (
          is.finite(Marshall) |
            is.finite(Millington_Quirk)
        )
    ]
    
    
    if (nrow(dt) == 0L) {
      
      return(NULL)
    }
    
    
    # ========================================================
    # Horizontal positions -> site value
    # at each original timestep
    # ========================================================
    
    dt <- dt[
      ,
      .(
        
        Marshall =
          mean_finite(
            Marshall
          ),
        
        Millington_Quirk =
          mean_finite(
            Millington_Quirk
          ),
        
        n_position_Marshall =
          sum(
            is.finite(
              Marshall
            )
          ),
        
        n_position_MQ =
          sum(
            is.finite(
              Millington_Quirk
            )
          )
      ),
      
      by = time
    ]
    
    
    return(
      dt
    )
  }
  
  
  flux_list <- lapply(
    flux_files,
    read_one_flux_file
  )
  
  
  flux_list <- Filter(
    Negate(is.null),
    flux_list
  )
  
  
  if (length(flux_list) > 0L) {
    
    soilResp_30min <- rbindlist(
      flux_list,
      use.names = TRUE,
      fill = TRUE
    )
    
    
    # Possible month-boundary duplicates
    soilResp_30min <- soilResp_30min[
      ,
      .(
        
        Marshall =
          mean_finite(
            Marshall
          ),
        
        Millington_Quirk =
          mean_finite(
            Millington_Quirk
          ),
        
        n_position_Marshall =
          max(
            n_position_Marshall,
            na.rm = TRUE
          ),
        
        n_position_MQ =
          max(
            n_position_MQ,
            na.rm = TRUE
          )
      ),
      
      by = time
    ]
    
    
    # --------------------------------------------------------
    # Exact 3-hour bins
    # --------------------------------------------------------
    
    soilResp_30min[
      ,
      time_3h :=
        floor_3hour(
          time
        )
    ]
    
    
    soilRespiration <- soilResp_30min[
      ,
      .(
        
        SoilResp_Marshall =
          mean_finite(
            Marshall
          ),
        
        SoilResp_Millington_Quirk =
          mean_finite(
            Millington_Quirk
          ),
        
        SoilResp_Marshall_sd =
          sd_finite(
            Marshall
          ),
        
        SoilResp_Millington_Quirk_sd =
          sd_finite(
            Millington_Quirk
          ),
        
        n_30min_Marshall =
          sum(
            is.finite(
              Marshall
            )
          ),
        
        n_30min_MQ =
          sum(
            is.finite(
              Millington_Quirk
            )
          ),
        
        mean_n_position_Marshall =
          mean_finite(
            n_position_Marshall
          ),
        
        mean_n_position_MQ =
          mean_finite(
            n_position_MQ
          )
      ),
      
      by = .(
        time = time_3h
      )
    ]
    
    
    soilRespiration <-
      soilRespiration[
        is.finite(
          SoilResp_Marshall
        ) |
          is.finite(
            SoilResp_Millington_Quirk
          )
      ]
    
    
  } else {
    
    soilRespiration <- data.table()
  }
  
  
  # ==========================================================
  # 7. Add lookup metadata
  # ==========================================================
  
  add_metadata <- function(x) {
    
    
    if (
      is.null(x) ||
      nrow(x) == 0L
    ) {
      
      return(x)
    }
    
    
    x <- copy(
      x
    )
    
    
    x[
      ,
      `:=`(
        
        index =
          site_index,
        
        AmeriFlux_ID =
          ameriflux_id,
        
        NEON_code =
          neon_code,
        
        NEON_name =
          neon_name
      )
    ]
    
    
    first_cols <- intersect(
      c(
        "time",
        "index",
        "AmeriFlux_ID",
        "NEON_code",
        "NEON_name",
        "verticalPosition",
        "mean_zOffset"
      ),
      names(x)
    )
    
    
    setcolorder(
      x,
      c(
        first_cols,
        setdiff(
          names(x),
          first_cols
        )
      )
    )
    
    
    setorder(
      x,
      time
    )
    
    
    return(
      x
    )
  }
  
  
  soilT <-
    add_metadata(
      soilT
    )
  
  
  soilMoisture <-
    add_metadata(
      soilMoisture
    )
  
  
  soilRespiration <-
    add_metadata(
      soilRespiration
    )
  
  
  # ==========================================================
  # 8. Depth summary
  # ==========================================================
  
  depth_summary <- data.table()
  
  
  if (nrow(soilT) > 0L) {
    
    x <- soilT[
      ,
      .(
        
        variable =
          "SoilT",
        
        mean_zOffset =
          mean_finite(
            mean_zOffset
          ),
        
        n_3h =
          .N,
        
        first_time =
          min(
            time
          ),
        
        last_time =
          max(
            time
          )
      ),
      
      by = verticalPosition
    ]
    
    
    depth_summary <- rbind(
      depth_summary,
      x,
      fill = TRUE
    )
  }
  
  
  if (
    nrow(
      soilMoisture
    ) > 0L
  ) {
    
    x <- soilMoisture[
      ,
      .(
        
        variable =
          "SoilMoisture",
        
        mean_zOffset =
          mean_finite(
            mean_zOffset
          ),
        
        n_3h =
          .N,
        
        first_time =
          min(
            time
          ),
        
        last_time =
          max(
            time
          )
      ),
      
      by = verticalPosition
    ]
    
    
    depth_summary <- rbind(
      depth_summary,
      x,
      fill = TRUE
    )
  }
  
  
  if (nrow(depth_summary) > 0L) {
    
    depth_summary[
      ,
      `:=`(
        
        index =
          site_index,
        
        NEON_code =
          neon_code
      )
    ]
    
    
    setcolorder(
      depth_summary,
      c(
        "index",
        "NEON_code",
        "variable",
        "verticalPosition",
        "mean_zOffset",
        "n_3h",
        "first_time",
        "last_time"
      )
    )
  }
  
  
  # ==========================================================
  # 9. Save
  # ==========================================================
  
  dir.create(
    output_dir,
    recursive = TRUE,
    showWarnings = FALSE
  )
  
  
  prefix <- paste0(
    "NEON_calibration_index_",
    site_index,
    "_",
    neon_code,
    "_",
    start_date,
    "_to_",
    end_date
  )
  
  
  soilT_file <- file.path(
    output_dir,
    paste0(
      prefix,
      "_SoilT_3hour_all_depths.csv"
    )
  )
  
  
  soilM_file <- file.path(
    output_dir,
    paste0(
      prefix,
      "_SoilMoisture_3hour_all_depths.csv"
    )
  )
  
  
  soilResp_file <- file.path(
    output_dir,
    paste0(
      prefix,
      "_SoilResp_3hour.csv"
    )
  )
  
  
  depth_file <- file.path(
    output_dir,
    paste0(
      prefix,
      "_depth_summary.csv"
    )
  )
  
  
  rds_file <- file.path(
    output_dir,
    paste0(
      prefix,
      "_ALL.rds"
    )
  )
  
  
  if (nrow(soilT) > 0L) {
    
    fwrite(
      soilT,
      soilT_file
    )
  }
  
  
  if (
    nrow(
      soilMoisture
    ) > 0L
  ) {
    
    fwrite(
      soilMoisture,
      soilM_file
    )
  }
  
  
  if (
    nrow(
      soilRespiration
    ) > 0L
  ) {
    
    fwrite(
      soilRespiration,
      soilResp_file
    )
  }
  
  
  if (
    nrow(
      depth_summary
    ) > 0L
  ) {
    
    fwrite(
      depth_summary,
      depth_file
    )
  }
  
  
  # ==========================================================
  # 10. Return object
  # ==========================================================
  
  result <- list(
    
    metadata =
      list(
        
        index =
          site_index,
        
        AmeriFlux_ID =
          ameriflux_id,
        
        NEON_code =
          neon_code,
        
        NEON_name =
          neon_name,
        
        start_date =
          start_date,
        
        end_date =
          end_date,
        
        n_env_files =
          length(
            env_files
          ),
        
        n_soilresp_files =
          length(
            flux_files
          )
      ),
    
    soilT =
      soilT,
    
    soilMoisture =
      soilMoisture,
    
    soilRespiration =
      soilRespiration,
    
    depth_summary =
      depth_summary
  )
  
  
  # No compression:
  # much faster readRDS() later
  saveRDS(
    result,
    rds_file,
    compress = FALSE
  )
  
  
  # ==========================================================
  # 11. Summary
  # ==========================================================
  
  elapsed <- as.numeric(
    difftime(
      Sys.time(),
      t0,
      units = "secs"
    )
  )
  
  
  cat(
    "\n============================================\n",
    "EXTRACTION FINISHED\n",
    "============================================\n",
    "Index: ", site_index, "\n",
    "Site:  ", neon_code, "\n\n",
    
    "ENV files read: ",
    length(env_files),
    "\n",
    
    "SoilResp files read: ",
    length(flux_files),
    "\n\n",
    
    "SoilT rows: ",
    nrow(soilT),
    "\n",
    
    "SoilT depths: ",
    if (nrow(soilT) > 0L) {
      
      paste(
        sort(
          unique(
            soilT$verticalPosition
          )
        ),
        collapse = ", "
      )
      
    } else {
      
      "NONE"
    },
    "\n\n",
    
    "SoilMoisture rows: ",
    nrow(soilMoisture),
    "\n",
    
    "SoilMoisture depths: ",
    if (nrow(soilMoisture) > 0L) {
      
      paste(
        sort(
          unique(
            soilMoisture$verticalPosition
          )
        ),
        collapse = ", "
      )
      
    } else {
      
      "NONE"
    },
    "\n\n",
    
    "SoilResp rows: ",
    nrow(soilRespiration),
    "\n\n",
    
    "Elapsed: ",
    round(
      elapsed,
      2
    ),
    " sec\n\n",
    
    "Saved RDS:\n",
    rds_file,
    "\n",
    
    "============================================\n",
    sep = ""
  )
  
  
  return(
    result
  )
}

#' Extract NEON soil calibration observations for all sites
#'
#' Extracts soil temperature, soil moisture, and soil respiration observations
#' for all NEON sites represented in a site lookup table. The function calls
#' `get_soil_neon_data_single_site()` independently for each model site index and
#' combines the resulting site-level tables.
#'
#' Only lookup entries with non-missing `index` and `NEON_code` values are
#' processed. Soil temperature and soil moisture retain all available vertical
#' positions. Soil respiration retains both the Marshall and Millington-Quirk
#' estimates. All dynamic observations are returned at exact 3-hour UTC
#' intervals, following the processing performed by
#' `get_soil_neon_data_single_site()`.
#'
#' Site-specific output files are written by `get_soil_neon_data_single_site()`.
#' After all sites are processed, this function additionally writes combined
#' CSV files for soil temperature, soil moisture, soil respiration, and soil
#' depth information, along with a processing-status table and an uncompressed
#' RDS file containing all combined results.
#'
#' A failure at one site does not stop processing of the remaining sites.
#' Errors are recorded in the returned status table.
#'
#' @md
#' @param lookup A data.frame or data.table containing the mapping between model
#'   site indices and NEON sites. Must contain `index` and `NEON_code`.
#'   `AmeriFlux_ID` and `NEON_name` are passed to
#'   `get_soil_neon_data_single_site()` and retained when available.
#' @param start_date Character string giving the first date to extract in
#'   `"YYYY-MM-DD"` format. The start date is inclusive.
#' @param end_date Character string giving the last date to extract in
#'   `"YYYY-MM-DD"` format. The end date is inclusive.
#' @param output_dir Directory where site-level and combined calibration data
#'   files will be saved. The directory is created if it does not already
#'   exist.
#' @param env_dir Directory containing John Zobitz's processed NEON
#'   environmental files (`env-meas-<SITE>-<YYYY-MM>.Rda`).
#' @param flux_dir Directory containing John Zobitz's processed NEON soil CO2
#'   flux files (`out-flux-<SITE>-<YYYY-MM>.Rda`).
#'
#' @return A list containing:
#'   * `soilT`: combined 3-hour soil temperature observations for all sites and
#'     all available vertical positions.
#'   * `soilMoisture`: combined 3-hour volumetric soil water content
#'     observations for all sites and all available vertical positions.
#'   * `soilRespiration`: combined 3-hour Marshall and Millington-Quirk soil
#'     respiration estimates for all sites.
#'   * `depth_summary`: combined soil temperature and soil moisture depth
#'     information for all sites.
#'   * `status`: processing status, record counts, and elapsed time for each
#'     requested site.
#'
#' @export
#' @author Yang Gu
get_soil_neon_data_multi_site <- function(
    lookup,
    start_date,
    end_date,
    output_dir,
    
    env_dir =
      "/projectnb/dietzelab/jzobitz/02-NEON-sites/env-data",
    
    flux_dir =
      "/projectnb/dietzelab/jzobitz/02-NEON-sites/flux-results"
) {
  
  suppressPackageStartupMessages({
    library(data.table)
  })
  
  
  # ==========================================================
  # Check required function
  # ==========================================================
  
  if (
    !exists(
      "get_soil_neon_data_single_site",
      mode = "function"
    )
  ) {
    
    stop(
      paste0(
        "get_soil_neon_data_single_site() is not loaded. ",
        "Source or run that function first."
      )
    )
  }
  
  
  # ==========================================================
  # Prepare lookup
  # ==========================================================
  
  lookup_dt <- as.data.table(
    copy(lookup)
  )
  
  
  required_cols <- c(
    "index",
    "NEON_code"
  )
  
  
  if (
    !all(
      required_cols %in%
      names(lookup_dt)
    )
  ) {
    
    stop(
      "lookup must contain: ",
      paste(
        required_cols,
        collapse = ", "
      )
    )
  }
  
  
  # ==========================================================
  # Keep unique NEON sites with valid indices
  # ==========================================================
  
  site_lookup <- unique(
    lookup_dt[
      !is.na(index) &
        !is.na(NEON_code) &
        NEON_code != "",
      .(
        index,
        
        AmeriFlux_ID =
          if (
            "AmeriFlux_ID" %in% names(lookup_dt)
          ) {
            AmeriFlux_ID
          } else {
            NA_character_
          },
        
        NEON_code,
        
        NEON_name =
          if (
            "NEON_name" %in% names(lookup_dt)
          ) {
            NEON_name
          } else {
            NA_character_
          }
      )
    ]
  )
  
  
  if (nrow(site_lookup) == 0L) {
    
    stop(
      "No valid NEON sites found in lookup."
    )
  }
  
  
  setorder(
    site_lookup,
    index
  )
  
  
  # ==========================================================
  # Output directory
  # ==========================================================
  
  dir.create(
    output_dir,
    recursive = TRUE,
    showWarnings = FALSE
  )
  
  
  # ==========================================================
  # Print run information
  # ==========================================================
  
  cat(
    "\n============================================\n",
    "ALL NEON CALIBRATION DATA\n",
    "============================================\n",
    "Sites:       ", nrow(site_lookup), "\n",
    "Start date:  ", start_date, "\n",
    "End date:    ", end_date, "\n",
    "Output dir:  ", output_dir, "\n",
    "============================================\n\n",
    sep = ""
  )
  
  
  # ==========================================================
  # Result containers
  # ==========================================================
  
  n_sites <- nrow(
    site_lookup
  )
  
  
  soilT_list <- vector(
    "list",
    n_sites
  )
  
  
  soilMoisture_list <- vector(
    "list",
    n_sites
  )
  
  
  soilRespiration_list <- vector(
    "list",
    n_sites
  )
  
  
  depth_summary_list <- vector(
    "list",
    n_sites
  )
  
  
  # ==========================================================
  # Status table
  # ==========================================================
  
  status <- data.table(
    
    index =
      site_lookup$index,
    
    NEON_code =
      site_lookup$NEON_code,
    
    success =
      FALSE,
    
    n_soilT =
      0L,
    
    n_soilT_depths =
      0L,
    
    n_soilMoisture =
      0L,
    
    n_soilMoisture_depths =
      0L,
    
    n_soilRespiration =
      0L,
    
    seconds =
      NA_real_,
    
    message =
      NA_character_
  )
  
  
  # ==========================================================
  # Process one NEON site at a time
  # ==========================================================
  
  total_start <- Sys.time()
  
  
  for (i in seq_len(n_sites)) {
    
    site_index <- site_lookup$index[i]
    
    neon_code <- site_lookup$NEON_code[i]
    
    
    cat(
      "\n--------------------------------------------\n",
      sprintf(
        "[%d / %d] index = %d | site = %s\n",
        i,
        n_sites,
        site_index,
        neon_code
      ),
      "--------------------------------------------\n",
      sep = ""
    )
    
    
    site_start <- Sys.time()
    
    
    result <- tryCatch(
      
      get_soil_neon_data_single_site(
        
        lookup =
          lookup_dt,
        
        index =
          site_index,
        
        start_date =
          start_date,
        
        end_date =
          end_date,
        
        output_dir =
          output_dir,
        
        env_dir =
          env_dir,
        
        flux_dir =
          flux_dir
      ),
      
      error = function(e) {
        
        message(
          "FAILED index ",
          site_index,
          " | ",
          neon_code,
          " | ",
          conditionMessage(e)
        )
        
        
        status[
          i,
          message :=
            conditionMessage(e)
        ]
        
        
        NULL
      }
    )
    
    
    # ========================================================
    # Elapsed time
    # ========================================================
    
    status[
      i,
      seconds :=
        as.numeric(
          difftime(
            Sys.time(),
            site_start,
            units = "secs"
          )
        )
    ]
    
    
    # ========================================================
    # Failed site
    # ========================================================
    
    if (is.null(result)) {
      
      if (is.na(status$message[i])) {
        
        status[
          i,
          message :=
            "Unknown processing failure"
        ]
      }
      
      next
    }
    
    
    # ========================================================
    # Store SoilT
    # ========================================================
    
    if (
      !is.null(result$soilT) &&
      nrow(result$soilT) > 0L
    ) {
      
      soilT_list[[i]] <-
        result$soilT
      
      
      status[
        i,
        n_soilT :=
          nrow(
            result$soilT
          )
      ]
      
      
      status[
        i,
        n_soilT_depths :=
          uniqueN(
            result$soilT$verticalPosition
          )
      ]
    }
    
    
    # ========================================================
    # Store SoilMoisture
    # ========================================================
    
    if (
      !is.null(
        result$soilMoisture
      ) &&
      nrow(
        result$soilMoisture
      ) > 0L
    ) {
      
      soilMoisture_list[[i]] <-
        result$soilMoisture
      
      
      status[
        i,
        n_soilMoisture :=
          nrow(
            result$soilMoisture
          )
      ]
      
      
      status[
        i,
        n_soilMoisture_depths :=
          uniqueN(
            result$soilMoisture$verticalPosition
          )
      ]
    }
    
    
    # ========================================================
    # Store SoilRespiration
    # ========================================================
    
    if (
      !is.null(
        result$soilRespiration
      ) &&
      nrow(
        result$soilRespiration
      ) > 0L
    ) {
      
      soilRespiration_list[[i]] <-
        result$soilRespiration
      
      
      status[
        i,
        n_soilRespiration :=
          nrow(
            result$soilRespiration
          )
      ]
    }
    
    
    # ========================================================
    # Store depth summary
    # ========================================================
    
    if (
      !is.null(
        result$depth_summary
      ) &&
      nrow(
        result$depth_summary
      ) > 0L
    ) {
      
      depth_summary_list[[i]] <-
        result$depth_summary
    }
    
    
    # ========================================================
    # Successful extraction
    #
    # Success means the function completed. Individual
    # variables can still be unavailable at some sites.
    # ========================================================
    
    status[
      i,
      `:=`(
        success =
          TRUE,
        
        message =
          "OK"
      )
    ]
    
    
    rm(
      result
    )
    
    
    gc(
      verbose = FALSE
    )
  }
  
  
  # ==========================================================
  # Combine all sites
  # ==========================================================
  
  soilT_all <- rbindlist(
    Filter(
      Negate(is.null),
      soilT_list
    ),
    use.names = TRUE,
    fill = TRUE
  )
  
  
  soilMoisture_all <- rbindlist(
    Filter(
      Negate(is.null),
      soilMoisture_list
    ),
    use.names = TRUE,
    fill = TRUE
  )
  
  
  soilRespiration_all <- rbindlist(
    Filter(
      Negate(is.null),
      soilRespiration_list
    ),
    use.names = TRUE,
    fill = TRUE
  )
  
  
  depth_summary_all <- rbindlist(
    Filter(
      Negate(is.null),
      depth_summary_list
    ),
    use.names = TRUE,
    fill = TRUE
  )
  
  
  # ==========================================================
  # Sort combined tables
  # ==========================================================
  
  if (nrow(soilT_all) > 0L) {
    
    setorder(
      soilT_all,
      index,
      verticalPosition,
      time
    )
  }
  
  
  if (nrow(soilMoisture_all) > 0L) {
    
    setorder(
      soilMoisture_all,
      index,
      verticalPosition,
      time
    )
  }
  
  
  if (nrow(soilRespiration_all) > 0L) {
    
    setorder(
      soilRespiration_all,
      index,
      time
    )
  }
  
  
  if (nrow(depth_summary_all) > 0L) {
    
    setorder(
      depth_summary_all,
      index,
      variable,
      verticalPosition
    )
  }
  
  
  # ==========================================================
  # Output file tag
  # ==========================================================
  
  date_tag <- paste0(
    start_date,
    "_to_",
    end_date
  )
  
  
  # ==========================================================
  # Save combined CSV files
  # ==========================================================
  
  soilT_file <- file.path(
    output_dir,
    paste0(
      "NEON_calibration_SoilT_ALL_",
      date_tag,
      ".csv"
    )
  )
  
  
  soilMoisture_file <- file.path(
    output_dir,
    paste0(
      "NEON_calibration_SoilMoisture_ALL_",
      date_tag,
      ".csv"
    )
  )
  
  
  soilRespiration_file <- file.path(
    output_dir,
    paste0(
      "NEON_calibration_SoilRespiration_ALL_",
      date_tag,
      ".csv"
    )
  )
  
  
  depth_file <- file.path(
    output_dir,
    paste0(
      "NEON_calibration_depth_summary_ALL_",
      date_tag,
      ".csv"
    )
  )
  
  
  status_file <- file.path(
    output_dir,
    paste0(
      "NEON_calibration_status_",
      date_tag,
      ".csv"
    )
  )
  
  
  if (nrow(soilT_all) > 0L) {
    
    fwrite(
      soilT_all,
      soilT_file
    )
  }
  
  
  if (nrow(soilMoisture_all) > 0L) {
    
    fwrite(
      soilMoisture_all,
      soilMoisture_file
    )
  }
  
  
  if (nrow(soilRespiration_all) > 0L) {
    
    fwrite(
      soilRespiration_all,
      soilRespiration_file
    )
  }
  
  
  if (nrow(depth_summary_all) > 0L) {
    
    fwrite(
      depth_summary_all,
      depth_file
    )
  }
  
  
  fwrite(
    status,
    status_file
  )
  
  
  # ==========================================================
  # Return object
  # ==========================================================
  
  result <- list(
    
    soilT =
      soilT_all,
    
    soilMoisture =
      soilMoisture_all,
    
    soilRespiration =
      soilRespiration_all,
    
    depth_summary =
      depth_summary_all,
    
    status =
      status
  )
  
  
  # ==========================================================
  # Save combined RDS
  #
  # Uncompressed for faster subsequent loading.
  # ==========================================================
  
  rds_file <- file.path(
    output_dir,
    paste0(
      "NEON_calibration_ALL_",
      date_tag,
      ".rds"
    )
  )
  
  
  saveRDS(
    result,
    rds_file,
    compress = FALSE
  )
  
  
  # ==========================================================
  # Final summary
  # ==========================================================
  
  elapsed_minutes <- as.numeric(
    difftime(
      Sys.time(),
      total_start,
      units = "mins"
    )
  )
  
  
  cat(
    "\n\n============================================\n",
    "ALL NEON CALIBRATION DATA FINISHED\n",
    "============================================\n",
    "Requested sites:             ",
    n_sites,
    "\n",
    
    "Successful sites:          ",
    sum(
      status$success
    ),
    "\n",
    
    "Failed sites:              ",
    sum(
      !status$success
    ),
    "\n\n",
    
    "Sites with SoilT:          ",
    sum(
      status$n_soilT > 0
    ),
    "\n",
    
    "Sites with SoilMoisture:   ",
    sum(
      status$n_soilMoisture > 0
    ),
    "\n",
    
    "Sites with SoilRespiration:",
    sum(
      status$n_soilRespiration > 0
    ),
    "\n\n",
    
    "Total SoilT rows:          ",
    nrow(
      soilT_all
    ),
    "\n",
    
    "Total SoilMoisture rows:   ",
    nrow(
      soilMoisture_all
    ),
    "\n",
    
    "Total SoilResp rows:       ",
    nrow(
      soilRespiration_all
    ),
    "\n\n",
    
    "Elapsed:                   ",
    round(
      elapsed_minutes,
      2
    ),
    " minutes\n\n",
    
    "Combined RDS:\n",
    rds_file,
    "\n",
    
    "============================================\n",
    sep = ""
  )
  
  
  return(
    result
  )
}

#' Extract ERA5 meteorological data for soil parameter calibration at a single site
#'
#' Extracts all time-varying meteorological variables from PEcAn-standardized
#' ERA5 NetCDF files for a single model site. The requested site is identified
#' using the numeric model index supplied in the site lookup table.
#'
#' ERA5 files are expected to follow the PEcAn directory structure:
#'
#' `ERA5_<index>_<member>/ERA5.<member>.<year>.nc`
#'
#' All time-varying variables present in the NetCDF files are retained. In
#' addition, meteorological variables used by PEcAn when generating SIPNET
#' meteorological forcing are calculated where the required source variables
#' are available. These include air temperature in degrees Celsius, wind speed,
#' precipitation per 3-hour timestep, PAR, relative humidity, vapor pressure
#' deficit, and atmospheric vapor pressure.
#'
#' ERA5 NetCDF time coordinates can accumulate small numerical drift around the
#' nominal 3-hour timestep. The raw time coordinate is therefore used only to
#' determine the first timestamp and to verify that the median timestep is
#' approximately 3 hours. The final time axis is reconstructed from row order
#' using exact 3-hour increments. All returned timestamps are in UTC.
#'
#' If `soil_temperature` is present in the standardized NetCDF file, soil
#' temperature in degrees Celsius and soil vapor pressure deficit are also
#' calculated. No soil-temperature approximation is generated when this
#' variable is absent.
#'
#' Both individual ERA5 ensemble-member data and ensemble-mean data at each
#' exact 3-hour UTC timestep are returned and saved.
#'
#' @md
#' @param lookup A data.frame or data.table containing site metadata. Must
#'   contain `index`. `AmeriFlux_ID`, `NEON_code`, `NEON_name`, `site_lat`,
#'   `site_lon`, `matched_grid_lat`, and `matched_grid_lon` are retained when
#'   available.
#' @param index Integer model site index used to identify the corresponding ERA5
#'   site directory.
#' @param start_date Character string giving the first date to extract in
#'   `"YYYY-MM-DD"` format. The start date is inclusive.
#' @param end_date Character string giving the last date to extract in
#'   `"YYYY-MM-DD"` format. The end date is inclusive.
#' @param output_dir Directory where extracted CSV and RDS files will be saved.
#'   The directory is created if it does not already exist.
#' @param input_root Root directory containing site-level PEcAn-standardized
#'   ERA5 directories.
#' @param members Integer vector giving ERA5 ensemble members to read. Default
#'   is `1:10`.
#' @param timestep_tolerance_seconds Maximum allowed difference, in seconds,
#'   between the median raw NetCDF timestep and the nominal 3-hour timestep.
#'   Default is 300 seconds.
#'
#' @return A list containing:
#'   * `metadata`: site identifiers, requested dates, and requested members.
#'   * `era5`: native and derived ERA5 variables for every available ensemble
#'     member at exact 3-hour UTC timesteps.
#'   * `era5_mean`: ensemble-mean ERA5 variables at each exact 3-hour UTC
#'     timestep.
#'   * `variable_info`: native NetCDF variable names, units, and long names.
#'   * `status`: processing status for every requested ensemble-member and year.
#'
#' @export
#' @author Yang Gu
get_soil_era5_data_single_site <- function(
    lookup,
    index,
    start_date,
    end_date,
    output_dir,
    input_root =
      "/projectnb/dietzelab/dongchen/anchorSites/NA_runs/ERA5_2012_2024",
    members = 1:10,
    timestep_tolerance_seconds = 300
) {
  
  suppressPackageStartupMessages({
    library(data.table)
    library(ncdf4)
  })
  
  
  # ==========================================================
  # 1. Prepare lookup
  # ==========================================================
  
  lookup_dt <- as.data.table(
    copy(lookup)
  )
  
  
  if (!"index" %in% names(lookup_dt)) {
    
    stop(
      "lookup must contain `index`."
    )
  }
  
  
  site_index <- as.integer(
    index
  )
  
  
  if (
    length(site_index) != 1L ||
    !is.finite(site_index)
  ) {
    
    stop(
      "`index` must be one numeric site index."
    )
  }
  
  
  site_row <- lookup_dt[
    index == site_index
  ]
  
  
  if (nrow(site_row) == 0L) {
    
    stop(
      "Index ",
      site_index,
      " was not found in lookup."
    )
  }
  
  
  site_row <- site_row[1L]
  
  
  # ==========================================================
  # 2. Extract lookup metadata
  # ==========================================================
  
  get_lookup_value <- function(
    column,
    default
  ) {
    
    if (column %in% names(site_row)) {
      
      value <- getElement(
        site_row,
        column
      )
      
      return(
        value[1L]
      )
    }
    
    
    return(
      default
    )
  }
  
  
  ameriflux_id <- as.character(
    get_lookup_value(
      "AmeriFlux_ID",
      NA_character_
    )
  )
  
  
  neon_code <- as.character(
    get_lookup_value(
      "NEON_code",
      NA_character_
    )
  )
  
  
  neon_name <- as.character(
    get_lookup_value(
      "NEON_name",
      NA_character_
    )
  )
  
  
  site_lat <- as.numeric(
    get_lookup_value(
      "site_lat",
      NA_real_
    )
  )
  
  
  site_lon <- as.numeric(
    get_lookup_value(
      "site_lon",
      NA_real_
    )
  )
  
  
  matched_grid_lat <- as.numeric(
    get_lookup_value(
      "matched_grid_lat",
      NA_real_
    )
  )
  
  
  matched_grid_lon <- as.numeric(
    get_lookup_value(
      "matched_grid_lon",
      NA_real_
    )
  )
  
  
  # ==========================================================
  # 3. Requested time range
  # ==========================================================
  
  start_time <- as.POSIXct(
    paste0(
      start_date,
      " 00:00:00"
    ),
    tz = "UTC"
  )
  
  
  end_time <- as.POSIXct(
    paste0(
      end_date,
      " 00:00:00"
    ),
    tz = "UTC"
  ) + 86400
  
  
  if (
    is.na(start_time) ||
    is.na(end_time)
  ) {
    
    stop(
      "Dates must use YYYY-MM-DD."
    )
  }
  
  
  if (end_time <= start_time) {
    
    stop(
      "end_date must be >= start_date."
    )
  }
  
  
  start_year <- as.integer(
    format(
      start_time,
      "%Y",
      tz = "UTC"
    )
  )
  
  
  end_year <- as.integer(
    format(
      end_time - 1,
      "%Y",
      tz = "UTC"
    )
  )
  
  
  years <- seq.int(
    start_year,
    end_year
  )
  
  
  members <- as.integer(
    members
  )
  
  
  if (length(members) == 0L) {
    
    stop(
      "`members` cannot be empty."
    )
  }
  
  
  # ==========================================================
  # 4. Output directory and file prefix
  # ==========================================================
  
  dir.create(
    output_dir,
    recursive = TRUE,
    showWarnings = FALSE
  )
  
  
  prefix <- paste0(
    "ERA5_soil_calibration_index_",
    site_index,
    "_",
    neon_code,
    "_",
    start_date,
    "_to_",
    end_date
  )
  
  
  status_file <- file.path(
    output_dir,
    paste0(
      prefix,
      "_status.csv"
    )
  )
  
  
  cat(
    "\n============================================\n",
    "ERA5 SOIL CALIBRATION DATA\n",
    "============================================\n",
    "Index:       ", site_index, "\n",
    "NEON code:   ", neon_code, "\n",
    "AmeriFlux:   ", ameriflux_id, "\n",
    "Start date:  ", start_date, "\n",
    "End date:    ", end_date, "\n",
    "Members:     ", paste(members, collapse = ", "), "\n",
    "============================================\n\n",
    sep = ""
  )
  
  
  # ==========================================================
  # 5. Helper: finite mean
  # ==========================================================
  
  mean_finite <- function(x) {
    
    x <- suppressWarnings(
      as.numeric(x)
    )
    
    
    x <- x[
      is.finite(x)
    ]
    
    
    if (length(x) == 0L) {
      
      return(
        NA_real_
      )
    }
    
    
    mean(x)
  }
  
  
  # ==========================================================
  # 6. Helper: NetCDF time -> UTC
  # ==========================================================
  
  parse_nc_time <- function(
    time_values,
    time_units
  ) {
    
    pattern <- paste0(
      "^\\s*",
      "(seconds|minutes|hours|days)",
      "\\s+since\\s+",
      "(.+)",
      "\\s*$"
    )
    
    
    match_result <- regexec(
      pattern,
      time_units,
      ignore.case = TRUE
    )
    
    
    matches <- regmatches(
      time_units,
      match_result
    )
    
    
    pieces <- unlist(
      matches,
      use.names = FALSE
    )
    
    
    if (length(pieces) != 3L) {
      
      stop(
        "Unsupported NetCDF time units: ",
        time_units
      )
    }
    
    
    unit_name <- tolower(
      pieces[2L]
    )
    
    
    origin_text <- pieces[3L]
    
    
    origin_text <- gsub(
      "T",
      " ",
      origin_text,
      fixed = TRUE
    )
    
    
    origin_text <- sub(
      "Z$",
      "",
      origin_text
    )
    
    
    origin_text <- sub(
      "\\s+UTC$",
      "",
      origin_text,
      ignore.case = TRUE
    )
    
    
    origin_text <- sub(
      "\\s*[+-][0-9]{2}:?[0-9]{2}$",
      "",
      origin_text
    )
    
    
    multiplier <- switch(
      unit_name,
      seconds = 1,
      minutes = 60,
      hours = 3600,
      days = 86400,
      stop(
        "Unsupported NetCDF time unit: ",
        unit_name
      )
    )
    
    
    origin <- as.POSIXct(
      origin_text,
      tz = "UTC"
    )
    
    
    if (is.na(origin)) {
      
      stop(
        "Cannot parse NetCDF time origin: ",
        origin_text
      )
    }
    
    
    origin +
      as.numeric(time_values) *
      multiplier
  }
  
  
  # ==========================================================
  # 7. Helper: saturation vapor pressure
  #
  # Approximation corresponding to PEcAn get.es().
  #
  # Input:
  #   temperature_c = degrees C
  #
  # Output:
  #   saturation vapor pressure in Pa
  # ==========================================================
  
  saturation_vapor_pressure_pa <- function(
    temperature_c
  ) {
    
    L <- 2.5e6
    Rv <- 461
    
    
    es_hpa <- 6.11 *
      exp(
        (L / Rv) *
          (
            1 / 273 -
              1 / (
                273 +
                  temperature_c
              )
          )
      )
    
    
    es_hpa * 100
  }
  
  
  # ==========================================================
  # 8. Helper: specific humidity -> relative humidity
  #
  # Same formulation used by PEcAn qair2rh().
  #
  # Output RH is a fraction from 0 to 1.
  # ==========================================================
  
  qair_to_rh <- function(
    qair,
    temp_c,
    press_pa
  ) {
    
    es_hpa <- 6.112 *
      exp(
        (
          17.67 *
            temp_c
        ) /
          (
            temp_c +
              243.5
          )
      )
    
    
    press_hpa <-
      press_pa /
      100
    
    
    e_hpa <-
      qair *
      press_hpa /
      (
        0.378 *
          qair +
          0.622
      )
    
    
    rh <-
      e_hpa /
      es_hpa
    
    
    rh[
      rh > 1
    ] <- 1
    
    
    rh[
      rh < 0
    ] <- 0
    
    
    rh
  }
  
  
  # ==========================================================
  # 9. Helper: shortwave -> PPFD
  #
  # Reproduces PEcAn sw2ppfd():
  #
  # SW -> PAR using 0.486
  # PAR -> photon flux using 2.35e5 J mol-1
  #
  # Output:
  #   umol photons m-2 s-1
  # ==========================================================
  
  shortwave_to_ppfd <- function(
    shortwave
  ) {
    
    par_w <-
      shortwave *
      0.486
    
    
    par_w /
      2.35e5 *
      1e6
  }
  
  
  # ==========================================================
  # 10. Helper: read one time-varying NetCDF variable
  #
  # getElement() is used to avoid nested-list indexing syntax.
  # ==========================================================
  
  read_time_variable <- function(
    nc,
    variable_name,
    n_time
  ) {
    
    variable <- getElement(
      nc$var,
      variable_name
    )
    
    
    if (is.null(variable)) {
      
      return(
        NULL
      )
    }
    
    
    variable_dims <- getElement(
      variable,
      "dim"
    )
    
    
    if (is.null(variable_dims)) {
      
      return(
        NULL
      )
    }
    
    
    dim_names <- vapply(
      variable_dims,
      function(x) {
        x$name
      },
      character(1)
    )
    
    
    if (
      !"time" %in%
      dim_names
    ) {
      
      return(
        NULL
      )
    }
    
    
    values <- tryCatch(
      
      ncdf4::ncvar_get(
        nc,
        variable_name
      ),
      
      error = function(e) {
        NULL
      }
    )
    
    
    if (is.null(values)) {
      
      return(
        NULL
      )
    }
    
    
    values <- as.numeric(
      values
    )
    
    
    if (
      length(values) != n_time
    ) {
      
      warning(
        "Skipping variable ",
        variable_name,
        ": expected ",
        n_time,
        " values but found ",
        length(values),
        "."
      )
      
      return(
        NULL
      )
    }
    
    
    return(
      values
    )
  }
  
  
  # ==========================================================
  # 11. Helper: add PEcAn/SIPNET-derived variables
  # ==========================================================
  
  add_derived_variables <- function(x) {
    
    # --------------------------------------------------------
    # Air temperature
    # --------------------------------------------------------
    
    if (
      "air_temperature" %in%
      names(x)
    ) {
      
      x[
        ,
        AirT_C :=
          air_temperature -
          273.15
      ]
    }
    
    
    # --------------------------------------------------------
    # Dew-point temperature
    # --------------------------------------------------------
    
    if (
      "dew_point_temperature" %in%
      names(x)
    ) {
      
      x[
        ,
        DewPoint_C :=
          dew_point_temperature -
          273.15
      ]
    }
    
    
    # --------------------------------------------------------
    # Wind speed
    # --------------------------------------------------------
    
    if (
      "wind_speed" %in%
      names(x)
    ) {
      
      x[
        ,
        WindSpeed :=
          wind_speed
      ]
      
    } else if (
      all(
        c(
          "eastward_wind",
          "northward_wind"
        ) %in%
        names(x)
      )
    ) {
      
      x[
        ,
        WindSpeed :=
          sqrt(
            eastward_wind^2 +
              northward_wind^2
          )
      ]
    }
    
    
    # --------------------------------------------------------
    # Precipitation per 3-hour timestep
    #
    # kg m-2 s-1 * 10800 s = kg m-2 = mm water
    # --------------------------------------------------------
    
    if (
      "precipitation_flux" %in%
      names(x)
    ) {
      
      x[
        ,
        Precip_mm_3h :=
          precipitation_flux *
          10800
      ]
    }
    
    
    # --------------------------------------------------------
    # PAR / PPFD
    # --------------------------------------------------------
    
    if (
      "surface_downwelling_photosynthetic_photon_flux_in_air" %in%
      names(x)
    ) {
      
      x[
        ,
        PAR_mol_m2_s :=
          surface_downwelling_photosynthetic_photon_flux_in_air
      ]
      
      
      x[
        ,
        PAR_umol_m2_s :=
          PAR_mol_m2_s *
          1e6
      ]
      
    } else if (
      "surface_downwelling_shortwave_flux_in_air" %in%
      names(x)
    ) {
      
      x[
        ,
        PAR_umol_m2_s :=
          shortwave_to_ppfd(
            surface_downwelling_shortwave_flux_in_air
          )
      ]
      
      
      x[
        ,
        PAR_mol_m2_s :=
          PAR_umol_m2_s *
          1e-6
      ]
    }
    
    
    if (
      "PAR_mol_m2_s" %in%
      names(x)
    ) {
      
      x[
        ,
        PAR_mol_m2_3h :=
          PAR_mol_m2_s *
          10800
      ]
    }
    
    
    # --------------------------------------------------------
    # RH, saturation vapor pressure, VPD, and vapor pressure
    # --------------------------------------------------------
    
    if (
      all(
        c(
          "specific_humidity",
          "AirT_C",
          "air_pressure"
        ) %in%
        names(x)
      )
    ) {
      
      x[
        ,
        RH :=
          qair_to_rh(
            specific_humidity,
            AirT_C,
            air_pressure
          )
      ]
      
      
      x[
        ,
        SVP_Pa :=
          saturation_vapor_pressure_pa(
            AirT_C
          )
      ]
      
      
      if (
        "water_vapor_saturation_deficit" %in%
        names(x)
      ) {
        
        x[
          ,
          VPD_Pa :=
            water_vapor_saturation_deficit
        ]
        
      } else {
        
        x[
          ,
          VPD_Pa :=
            SVP_Pa *
            (
              1 -
                RH
            )
        ]
      }
      
      
      x[
        ,
        AirVP_Pa :=
          SVP_Pa -
          VPD_Pa
      ]
    }
    
    
    # --------------------------------------------------------
    # Soil temperature
    #
    # Only calculate if soil_temperature actually exists.
    # Do not generate the old PEcAn tau approximation here.
    # --------------------------------------------------------
    
    if (
      "soil_temperature" %in%
      names(x)
    ) {
      
      x[
        ,
        SoilT_C :=
          soil_temperature -
          273.15
      ]
      
      
      if (
        all(
          c(
            "specific_humidity",
            "air_pressure"
          ) %in%
          names(x)
        )
      ) {
        
        soil_svp <-
          saturation_vapor_pressure_pa(
            x$SoilT_C
          )
        
        
        soil_rh <-
          qair_to_rh(
            x$specific_humidity,
            x$SoilT_C,
            x$air_pressure
          )
        
        
        x[
          ,
          VPDsoil_Pa :=
            soil_svp *
            (
              1 -
                soil_rh
            )
        ]
      }
    }
    
    
    return(
      x
    )
  }
  
  
  # ==========================================================
  # 12. Helper: read one annual ERA5 NetCDF file
  # ==========================================================
  
  read_one_file <- function(
    nc_file,
    member_i,
    year_i
  ) {
    
    nc <- ncdf4::nc_open(
      nc_file
    )
    
    
    on.exit(
      ncdf4::nc_close(
        nc
      ),
      add = TRUE
    )
    
    
    # --------------------------------------------------------
    # Read time dimension
    # --------------------------------------------------------
    
    time_dim <- getElement(
      nc$dim,
      "time"
    )
    
    
    if (is.null(time_dim)) {
      
      stop(
        "No time dimension in ",
        nc_file
      )
    }
    
    
    time_values <- getElement(
      time_dim,
      "vals"
    )
    
    
    time_units <- getElement(
      time_dim,
      "units"
    )
    
    
    if (
      is.null(time_values) ||
      length(time_values) == 0L
    ) {
      
      stop(
        "Empty time dimension in ",
        nc_file
      )
    }
    
    
    if (
      is.null(time_units) ||
      length(time_units) == 0L
    ) {
      
      stop(
        "Missing time units in ",
        nc_file
      )
    }
    
    
    raw_time <- parse_nc_time(
      time_values =
        time_values,
      
      time_units =
        time_units
    )
    
    
    n_time <- length(
      raw_time
    )
    
    
    # --------------------------------------------------------
    # Check NOMINAL 3-hour timestep
    #
    # Raw NetCDF time coordinates may have small accumulated
    # floating-point drift. Therefore, the raw timestep is not
    # required to equal exactly 10800 seconds.
    # --------------------------------------------------------
    
    if (n_time > 1L) {
      
      raw_step_seconds <- median(
        diff(
          as.numeric(
            raw_time
          )
        ),
        na.rm = TRUE
      )
      
      
      if (!is.finite(raw_step_seconds)) {
        
        stop(
          "Cannot determine timestep in ",
          nc_file
        )
      }
      
      
      raw_step_hours <-
        raw_step_seconds /
        3600
      
      
      if (
        abs(
          raw_step_seconds -
          10800
        ) >
        timestep_tolerance_seconds
      ) {
        
        stop(
          "ERA5 timestep is not approximately 3 hours. Found ",
          round(
            raw_step_hours,
            6
          ),
          " hours in ",
          nc_file
        )
      }
    }
    
    
    # --------------------------------------------------------
    # Exact UTC time reconstruction
    #
    # IMPORTANT:
    #
    # Use ONLY the first raw timestamp.
    #
    # Every later timestamp is generated using row order:
    #
    # t[i] = t[1] + (i - 1) * 3 hours
    #
    # This removes the accumulating numerical drift in the raw
    # NetCDF time coordinate.
    # --------------------------------------------------------
    
    first_raw_seconds <- as.numeric(
      raw_time[1L]
    )
    
    
    first_exact_seconds <- round(
      first_raw_seconds /
        10800
    ) *
      10800
    
    
    first_datetime <- as.POSIXct(
      first_exact_seconds,
      origin = "1970-01-01",
      tz = "UTC"
    )
    
    
    exact_time <-
      first_datetime +
      (
        seq_len(
          n_time
        ) -
          1L
      ) *
      10800
    
    
    # --------------------------------------------------------
    # Read all time-varying NetCDF variables
    # --------------------------------------------------------
    
    x <- data.table(
      time =
        exact_time
    )
    
    
    variable_names <- names(
      nc$var
    )
    
    
    variables_read <- character()
    
    
    for (variable_name in variable_names) {
      
      values <- read_time_variable(
        nc =
          nc,
        
        variable_name =
          variable_name,
        
        n_time =
          n_time
      )
      
      
      if (!is.null(values)) {
        
        set(
          x,
          j =
            variable_name,
          value =
            values
        )
        
        
        variables_read <- c(
          variables_read,
          variable_name
        )
      }
    }
    
    
    # --------------------------------------------------------
    # Collect native NetCDF variable metadata
    # --------------------------------------------------------
    
    variable_info_list <- lapply(
      variables_read,
      function(variable_name) {
        
        variable <- getElement(
          nc$var,
          variable_name
        )
        
        
        units <- getElement(
          variable,
          "units"
        )
        
        
        long_name <- getElement(
          variable,
          "longname"
        )
        
        
        if (
          is.null(units) ||
          length(units) == 0L
        ) {
          
          units <- NA_character_
        }
        
        
        if (
          is.null(long_name) ||
          length(long_name) == 0L
        ) {
          
          long_name <- NA_character_
        }
        
        
        data.table(
          variable =
            variable_name,
          
          units =
            as.character(
              units[1L]
            ),
          
          long_name =
            as.character(
              long_name[1L]
            )
        )
      }
    )
    
    
    variable_info <- rbindlist(
      variable_info_list,
      use.names = TRUE,
      fill = TRUE
    )
    
    
    # --------------------------------------------------------
    # Keep requested date range only
    # --------------------------------------------------------
    
    x <- x[
      time >= start_time &
        time < end_time
    ]
    
    
    if (nrow(x) == 0L) {
      
      return(
        NULL
      )
    }
    
    
    # --------------------------------------------------------
    # Add derived meteorological variables
    # --------------------------------------------------------
    
    x <- add_derived_variables(
      x
    )
    
    
    # --------------------------------------------------------
    # Calendar fields based on exact reconstructed UTC time
    # --------------------------------------------------------
    
    x[
      ,
      year :=
        as.integer(
          format(
            time,
            "%Y",
            tz = "UTC"
          )
        )
    ]
    
    
    x[
      ,
      doy :=
        as.integer(
          format(
            time,
            "%j",
            tz = "UTC"
          )
        )
    ]
    
    
    x[
      ,
      hour :=
        as.integer(
          format(
            time,
            "%H",
            tz = "UTC"
          )
        )
    ]
    
    
    x[
      ,
      `:=`(
        index =
          site_index,
        
        member =
          member_i,
        
        source_year =
          year_i
      )
    ]
    
    
    return(
      list(
        data =
          x,
        
        variable_info =
          variable_info
      )
    )
  }
  
  
  # ==========================================================
  # 13. Create member x year jobs
  # ==========================================================
  
  jobs <- CJ(
    member =
      members,
    
    source_year =
      years,
    
    unique =
      TRUE
  )
  
  
  status <- copy(
    jobs
  )
  
  
  status[
    ,
    `:=`(
      file =
        NA_character_,
      
      success =
        FALSE,
      
      n_timestep =
        0L,
      
      n_variable =
        0L,
      
      message =
        NA_character_
    )
  ]
  
  
  data_list <- vector(
    "list",
    nrow(jobs)
  )
  
  
  info_list <- vector(
    "list",
    nrow(jobs)
  )
  
  
  total_start <- Sys.time()
  
  
  # ==========================================================
  # 14. Read all requested ERA5 files
  # ==========================================================
  
  for (i in seq_len(nrow(jobs))) {
    
    member_i <- jobs$member[i]
    
    year_i <- jobs$source_year[i]
    
    
    input_dir <- file.path(
      input_root,
      paste0(
        "ERA5_",
        site_index,
        "_",
        member_i
      )
    )
    
    
    nc_file <- file.path(
      input_dir,
      paste0(
        "ERA5.",
        member_i,
        ".",
        year_i,
        ".nc"
      )
    )
    
    
    status[
      i,
      file :=
        nc_file
    ]
    
    
    if (!file.exists(nc_file)) {
      
      status[
        i,
        message :=
          "FILE_MISSING"
      ]
      
      next
    }
    
    
    cat(
      sprintf(
        "[%d / %d] member = %d | year = %d\n",
        i,
        nrow(jobs),
        member_i,
        year_i
      )
    )
    
    
    one <- tryCatch(
      
      read_one_file(
        nc_file =
          nc_file,
        
        member_i =
          member_i,
        
        year_i =
          year_i
      ),
      
      error = function(e) {
        
        error_message <- conditionMessage(
          e
        )
        
        
        status[
          i,
          message :=
            error_message
        ]
        
        
        message(
          "FAILED member ",
          member_i,
          " | year ",
          year_i,
          " | ",
          error_message
        )
        
        
        NULL
      }
    )
    
    
    if (is.null(one)) {
      
      if (is.na(status$message[i])) {
        
        status[
          i,
          message :=
            "NO_DATA"
        ]
      }
      
      next
    }
    
    
    one_data <- getElement(
      one,
      "data"
    )
    
    
    one_info <- getElement(
      one,
      "variable_info"
    )
    
    
    data_list[i] <- list(
      one_data
    )
    
    
    info_list[i] <- list(
      one_info
    )
    
    
    status[
      i,
      `:=`(
        success =
          TRUE,
        
        n_timestep =
          nrow(
            one_data
          ),
        
        n_variable =
          nrow(
            one_info
          ),
        
        message =
          "OK"
      )
    ]
  }
  
  
  # ==========================================================
  # 15. Save status before combining
  #
  # This preserves diagnostic information even if every file
  # fails.
  # ==========================================================
  
  fwrite(
    status,
    status_file
  )
  
  
  # ==========================================================
  # 16. Combine available ERA5 files
  # ==========================================================
  
  valid_data <- Filter(
    Negate(is.null),
    data_list
  )
  
  
  if (length(valid_data) == 0L) {
    
    stop(
      paste0(
        "No valid ERA5 files were read for index ",
        site_index,
        ". Check processing status at:\n",
        status_file
      )
    )
  }
  
  
  era5 <- rbindlist(
    valid_data,
    use.names = TRUE,
    fill = TRUE
  )
  
  
  # ----------------------------------------------------------
  # Detect duplicate member-time records
  # ----------------------------------------------------------
  
  duplicate_records <- era5[
    ,
    .N,
    by = .(
      member,
      time
    )
  ][
    N > 1L
  ]
  
  
  if (nrow(duplicate_records) > 0L) {
    
    warning(
      "Duplicate member-time ERA5 records were found. ",
      "Only the first record is retained."
    )
    
    
    era5 <- unique(
      era5,
      by = c(
        "member",
        "time"
      )
    )
  }
  
  
  # ==========================================================
  # 17. Add site metadata
  # ==========================================================
  
  era5[
    ,
    `:=`(
      AmeriFlux_ID =
        ameriflux_id,
      
      NEON_code =
        neon_code,
      
      NEON_name =
        neon_name,
      
      site_lat =
        site_lat,
      
      site_lon =
        site_lon,
      
      matched_grid_lat =
        matched_grid_lat,
      
      matched_grid_lon =
        matched_grid_lon
    )
  ]
  
  
  first_columns <- c(
    "time",
    "index",
    "AmeriFlux_ID",
    "NEON_code",
    "NEON_name",
    "site_lat",
    "site_lon",
    "matched_grid_lat",
    "matched_grid_lon",
    "year",
    "doy",
    "hour",
    "member",
    "source_year"
  )
  
  
  first_columns <- intersect(
    first_columns,
    names(era5)
  )
  
  
  setcolorder(
    era5,
    c(
      first_columns,
      setdiff(
        names(era5),
        first_columns
      )
    )
  )
  
  
  setorder(
    era5,
    member,
    time
  )
  
  
  # ==========================================================
  # 18. Native variable information
  # ==========================================================
  
  valid_info <- Filter(
    Negate(is.null),
    info_list
  )
  
  
  if (length(valid_info) > 0L) {
    
    variable_info <- rbindlist(
      valid_info,
      use.names = TRUE,
      fill = TRUE
    )
    
    
    variable_info <- unique(
      variable_info
    )
    
    
    setorder(
      variable_info,
      variable
    )
    
  } else {
    
    variable_info <- data.table()
  }
  
  
  # ==========================================================
  # 19. Ensemble mean
  # ==========================================================
  
  numeric_columns <- names(
    era5
  )[
    vapply(
      era5,
      is.numeric,
      logical(1)
    )
  ]
  
  
  metadata_numeric <- c(
    "index",
    "site_lat",
    "site_lon",
    "matched_grid_lat",
    "matched_grid_lon",
    "year",
    "doy",
    "hour",
    "member",
    "source_year"
  )
  
  
  value_columns <- setdiff(
    numeric_columns,
    metadata_numeric
  )
  
  
  era5_mean <- era5[
    ,
    c(
      lapply(
        .SD,
        mean_finite
      ),
      
      list(
        n_ensemble =
          uniqueN(
            member
          )
      )
    ),
    by = time,
    .SDcols = value_columns
  ]
  
  
  # ==========================================================
  # Recalculate calendar fields from exact UTC time
  # ==========================================================
  
  era5_mean[
    ,
    year :=
      as.integer(
        format(
          time,
          "%Y",
          tz = "UTC"
        )
      )
  ]
  
  
  era5_mean[
    ,
    doy :=
      as.integer(
        format(
          time,
          "%j",
          tz = "UTC"
        )
      )
  ]
  
  
  era5_mean[
    ,
    hour :=
      as.integer(
        format(
          time,
          "%H",
          tz = "UTC"
        )
      )
  ]
  
  
  era5_mean[
    ,
    `:=`(
      index =
        site_index,
      
      AmeriFlux_ID =
        ameriflux_id,
      
      NEON_code =
        neon_code,
      
      NEON_name =
        neon_name,
      
      site_lat =
        site_lat,
      
      site_lon =
        site_lon,
      
      matched_grid_lat =
        matched_grid_lat,
      
      matched_grid_lon =
        matched_grid_lon
    )
  ]
  
  
  mean_first_columns <- c(
    "time",
    "index",
    "AmeriFlux_ID",
    "NEON_code",
    "NEON_name",
    "site_lat",
    "site_lon",
    "matched_grid_lat",
    "matched_grid_lon",
    "year",
    "doy",
    "hour",
    "n_ensemble"
  )
  
  
  mean_first_columns <- intersect(
    mean_first_columns,
    names(era5_mean)
  )
  
  
  setcolorder(
    era5_mean,
    c(
      mean_first_columns,
      setdiff(
        names(era5_mean),
        mean_first_columns
      )
    )
  )
  
  
  setorder(
    era5_mean,
    time
  )
  
  
  # ==========================================================
  # 20. Verify exact reconstructed 3-hour time axis
  # ==========================================================
  
  if (nrow(era5_mean) > 1L) {
    
    time_steps <- unique(
      diff(
        as.numeric(
          era5_mean$time
        )
      )
    )
    
    
    time_steps <- time_steps[
      is.finite(
        time_steps
      )
    ]
    
    
    if (
      length(time_steps) > 0L &&
      any(
        time_steps != 10800
      )
    ) {
      
      warning(
        "Combined ERA5 mean contains time gaps. ",
        "This can occur when annual files or ensemble members are missing."
      )
    }
  }
  
  
  # ==========================================================
  # 21. Save output
  # ==========================================================
  
  all_members_file <- file.path(
    output_dir,
    paste0(
      prefix,
      "_all_members.csv"
    )
  )
  
  
  mean_file <- file.path(
    output_dir,
    paste0(
      prefix,
      "_ensemble_mean.csv"
    )
  )
  
  
  variable_file <- file.path(
    output_dir,
    paste0(
      prefix,
      "_variable_info.csv"
    )
  )
  
  
  rds_file <- file.path(
    output_dir,
    paste0(
      prefix,
      "_ALL.rds"
    )
  )
  
  
  fwrite(
    era5,
    all_members_file
  )
  
  
  fwrite(
    era5_mean,
    mean_file
  )
  
  
  fwrite(
    variable_info,
    variable_file
  )
  
  
  # Status has already been written above, but write again so
  # the final version is guaranteed to match the return object.
  fwrite(
    status,
    status_file
  )
  
  
  # ==========================================================
  # 22. Return object
  # ==========================================================
  
  result <- list(
    metadata =
      list(
        index =
          site_index,
        
        AmeriFlux_ID =
          ameriflux_id,
        
        NEON_code =
          neon_code,
        
        NEON_name =
          neon_name,
        
        start_date =
          start_date,
        
        end_date =
          end_date,
        
        members =
          members,
        
        input_root =
          input_root,
        
        timestep_tolerance_seconds =
          timestep_tolerance_seconds
      ),
    
    era5 =
      era5,
    
    era5_mean =
      era5_mean,
    
    variable_info =
      variable_info,
    
    status =
      status
  )
  
  
  saveRDS(
    result,
    rds_file,
    compress = FALSE
  )
  
  
  # ==========================================================
  # 23. Summary
  # ==========================================================
  
  elapsed <- as.numeric(
    difftime(
      Sys.time(),
      total_start,
      units = "secs"
    )
  )
  
  
  hours_present <- sort(
    unique(
      as.integer(
        format(
          era5_mean$time,
          "%H",
          tz = "UTC"
        )
      )
    )
  )
  
  
  cat(
    "\n============================================\n",
    "ERA5 EXTRACTION FINISHED\n",
    "============================================\n",
    "Index:              ", site_index, "\n",
    "Site:               ", neon_code, "\n",
    "Successful files:   ", sum(status$success), "\n",
    "Missing/failed:     ", sum(!status$success), "\n",
    "Members available:  ", uniqueN(era5$member), "\n",
    "All-member rows:    ", nrow(era5), "\n",
    "Ensemble mean rows: ", nrow(era5_mean), "\n",
    "Native variables:   ", nrow(variable_info), "\n",
    "UTC hours present:  ", paste(hours_present, collapse = ", "), "\n",
    "Elapsed:            ", round(elapsed, 2), " sec\n",
    "Saved RDS:          ", rds_file, "\n",
    "============================================\n",
    sep = ""
  )
  
  
  return(
    result
  )
}

#' Extract ERA5 meteorological data for soil parameter calibration for multiple sites
#'
#' Extracts PEcAn-standardized ERA5 meteorological data for all model site
#' indices represented in a site lookup table. The function calls
#' `get_soil_era5_data_single_site()` independently for each unique model site
#' index and combines the resulting ensemble-mean meteorological data.
#'
#' All lookup entries with non-missing `index` values are processed. Site
#' metadata, including AmeriFlux and NEON identifiers, are retained when
#' available. All dynamic meteorological data use the exact 3-hour UTC time
#' axis reconstructed by `get_soil_era5_data_single_site()`.
#'
#' Site-specific CSV and RDS files are written by
#' `get_soil_era5_data_single_site()`. After all sites are processed, this
#' function writes a combined ensemble-mean ERA5 table, combined variable
#' metadata, file-level processing status, and site-level processing status.
#'
#' By default, individual ensemble-member data are not combined across sites
#' because the resulting table can be very large. The individual member data
#' remain available in the site-specific files written by
#' `get_soil_era5_data_single_site()`. Set `combine_all_members = TRUE` to
#' additionally combine and save all member-level ERA5 data.
#'
#' A failure at one site does not stop processing of the remaining sites.
#' Errors are recorded in the returned site-level status table.
#'
#' @md
#' @param lookup A data.frame or data.table containing site metadata. Must
#'   contain `index`. Each unique non-missing index is processed once.
#' @param start_date Character string giving the first date to extract in
#'   `"YYYY-MM-DD"` format. The start date is inclusive.
#' @param end_date Character string giving the last date to extract in
#'   `"YYYY-MM-DD"` format. The end date is inclusive.
#' @param output_dir Directory where site-specific and combined ERA5 data files
#'   will be saved. The directory is created if it does not already exist.
#' @param input_root Root directory containing site-level PEcAn-standardized
#'   ERA5 directories.
#' @param members Integer vector giving ERA5 ensemble members to read. Default
#'   is `1:10`.
#' @param timestep_tolerance_seconds Maximum allowed difference, in seconds,
#'   between the median raw NetCDF timestep and the nominal 3-hour timestep.
#'   Default is 300 seconds.
#' @param combine_all_members Logical indicating whether member-level ERA5 data
#'   from all sites should also be combined in memory and written to disk.
#'   Default is `FALSE`.
#'
#' @return A list containing:
#'   * `era5_mean`: combined ensemble-mean ERA5 data for all successfully
#'     processed sites at exact 3-hour UTC timesteps.
#'   * `era5`: combined member-level ERA5 data when
#'     `combine_all_members = TRUE`; otherwise `NULL`.
#'   * `variable_info`: native NetCDF variable metadata encountered across all
#'     successfully processed sites.
#'   * `file_status`: processing status for each site, ensemble member, and
#'     annual ERA5 file.
#'   * `site_status`: site-level processing status, record counts, and elapsed
#'     time.
#'
#' @export
#' @author Yang Gu
get_soil_era5_data_multi_site <- function(
    lookup,
    start_date,
    end_date,
    output_dir,
    input_root =
      "/projectnb/dietzelab/dongchen/anchorSites/NA_runs/ERA5_2012_2024",
    members = 1:10,
    timestep_tolerance_seconds = 300,
    combine_all_members = FALSE
) {
  
  suppressPackageStartupMessages({
    library(data.table)
  })
  
  
  # ==========================================================
  # 1. Check required single-site function
  # ==========================================================
  
  if (
    !exists(
      "get_soil_era5_data_single_site",
      mode = "function"
    )
  ) {
    
    stop(
      paste0(
        "get_soil_era5_data_single_site() is not loaded. ",
        "Source or run that function first."
      )
    )
  }
  
  
  # ==========================================================
  # 2. Prepare lookup
  # ==========================================================
  
  lookup_dt <- as.data.table(
    copy(lookup)
  )
  
  
  if (!"index" %in% names(lookup_dt)) {
    
    stop(
      "lookup must contain `index`."
    )
  }
  
  
  indices <- sort(
    unique(
      as.integer(
        lookup_dt[
          !is.na(index),
          index
        ]
      )
    )
  )
  
  
  indices <- indices[
    is.finite(
      indices
    )
  ]
  
  
  if (length(indices) == 0L) {
    
    stop(
      "No valid site indices were found in lookup."
    )
  }
  
  
  # ==========================================================
  # 3. Output directory
  # ==========================================================
  
  dir.create(
    output_dir,
    recursive = TRUE,
    showWarnings = FALSE
  )
  
  
  # ==========================================================
  # 4. Print run information
  # ==========================================================
  
  cat(
    "\n============================================\n",
    "ALL-SITE ERA5 SOIL CALIBRATION DATA\n",
    "============================================\n",
    "Sites:       ", length(indices), "\n",
    "Start date:  ", start_date, "\n",
    "End date:    ", end_date, "\n",
    "Members:     ", paste(members, collapse = ", "), "\n",
    "Combine all members: ", combine_all_members, "\n",
    "Output dir:  ", output_dir, "\n",
    "============================================\n\n",
    sep = ""
  )
  
  
  # ==========================================================
  # 5. Result containers
  # ==========================================================
  
  n_sites <- length(
    indices
  )
  
  
  era5_mean_list <- vector(
    "list",
    n_sites
  )
  
  
  variable_info_list <- vector(
    "list",
    n_sites
  )
  
  
  file_status_list <- vector(
    "list",
    n_sites
  )
  
  
  if (combine_all_members) {
    
    era5_list <- vector(
      "list",
      n_sites
    )
    
  } else {
    
    era5_list <- NULL
  }
  
  
  # ==========================================================
  # 6. Site-level status table
  # ==========================================================
  
  site_status <- data.table(
    index =
      indices,
    
    NEON_code =
      NA_character_,
    
    AmeriFlux_ID =
      NA_character_,
    
    success =
      FALSE,
    
    n_mean_timestep =
      0L,
    
    n_member_rows =
      0L,
    
    n_members_available =
      0L,
    
    n_native_variables =
      0L,
    
    n_files_success =
      0L,
    
    n_files_failed =
      0L,
    
    seconds =
      NA_real_,
    
    message =
      NA_character_
  )
  
  
  total_start <- Sys.time()
  
  
  # ==========================================================
  # 7. Process one site at a time
  # ==========================================================
  
  for (i in seq_along(indices)) {
    
    site_index <- indices[i]
    
    
    cat(
      "\n--------------------------------------------\n",
      sprintf(
        "[%d / %d] index = %d\n",
        i,
        n_sites,
        site_index
      ),
      "--------------------------------------------\n",
      sep = ""
    )
    
    
    site_start <- Sys.time()
    
    
    result <- tryCatch(
      
      get_soil_era5_data_single_site(
        lookup =
          lookup_dt,
        
        index =
          site_index,
        
        start_date =
          start_date,
        
        end_date =
          end_date,
        
        output_dir =
          output_dir,
        
        input_root =
          input_root,
        
        members =
          members,
        
        timestep_tolerance_seconds =
          timestep_tolerance_seconds
      ),
      
      error = function(e) {
        
        error_message <- conditionMessage(
          e
        )
        
        
        site_status[
          i,
          message :=
            error_message
        ]
        
        
        message(
          "FAILED index ",
          site_index,
          " | ",
          error_message
        )
        
        
        NULL
      }
    )
    
    
    site_status[
      i,
      seconds :=
        as.numeric(
          difftime(
            Sys.time(),
            site_start,
            units = "secs"
          )
        )
    ]
    
    
    # ========================================================
    # Failed site
    # ========================================================
    
    if (is.null(result)) {
      
      if (is.na(site_status$message[i])) {
        
        site_status[
          i,
          message :=
            "Unknown processing failure"
        ]
      }
      
      next
    }
    
    
    # ========================================================
    # Extract returned objects
    #
    # getElement() is used consistently to avoid nested-list
    # indexing syntax problems.
    # ========================================================
    
    metadata_i <- getElement(
      result,
      "metadata"
    )
    
    
    era5_i <- getElement(
      result,
      "era5"
    )
    
    
    era5_mean_i <- getElement(
      result,
      "era5_mean"
    )
    
    
    variable_info_i <- getElement(
      result,
      "variable_info"
    )
    
    
    file_status_i <- getElement(
      result,
      "status"
    )
    
    
    # ========================================================
    # Site metadata
    # ========================================================
    
    if (!is.null(metadata_i)) {
      
      neon_code_i <- getElement(
        metadata_i,
        "NEON_code"
      )
      
      
      ameriflux_i <- getElement(
        metadata_i,
        "AmeriFlux_ID"
      )
      
      
      if (
        !is.null(neon_code_i) &&
        length(neon_code_i) > 0L
      ) {
        
        site_status[
          i,
          NEON_code :=
            as.character(
              neon_code_i[1L]
            )
        ]
      }
      
      
      if (
        !is.null(ameriflux_i) &&
        length(ameriflux_i) > 0L
      ) {
        
        site_status[
          i,
          AmeriFlux_ID :=
            as.character(
              ameriflux_i[1L]
            )
        ]
      }
    }
    
    
    # ========================================================
    # Store ensemble mean
    # ========================================================
    
    if (
      !is.null(era5_mean_i) &&
      nrow(era5_mean_i) > 0L
    ) {
      
      era5_mean_list[i] <- list(
        era5_mean_i
      )
      
      
      site_status[
        i,
        n_mean_timestep :=
          nrow(
            era5_mean_i
          )
      ]
    }
    
    
    # ========================================================
    # Member-level data
    #
    # Store only when explicitly requested.
    # ========================================================
    
    if (
      !is.null(era5_i) &&
      nrow(era5_i) > 0L
    ) {
      
      site_status[
        i,
        `:=`(
          n_member_rows =
            nrow(
              era5_i
            ),
          
          n_members_available =
            uniqueN(
              era5_i$member
            )
        )
      ]
      
      
      if (combine_all_members) {
        
        era5_list[i] <- list(
          era5_i
        )
      }
    }
    
    
    # ========================================================
    # Variable information
    # ========================================================
    
    if (
      !is.null(variable_info_i) &&
      nrow(variable_info_i) > 0L
    ) {
      
      variable_info_i <- copy(
        variable_info_i
      )
      
      
      variable_info_i[
        ,
        index :=
          site_index
      ]
      
      
      variable_info_list[i] <- list(
        variable_info_i
      )
      
      
      site_status[
        i,
        n_native_variables :=
          uniqueN(
            variable_info_i$variable
          )
      ]
    }
    
    
    # ========================================================
    # File-level status
    # ========================================================
    
    if (
      !is.null(file_status_i) &&
      nrow(file_status_i) > 0L
    ) {
      
      file_status_i <- copy(
        file_status_i
      )
      
      
      file_status_i[
        ,
        index :=
          site_index
      ]
      
      
      file_status_list[i] <- list(
        file_status_i
      )
      
      
      site_status[
        i,
        `:=`(
          n_files_success =
            sum(
              file_status_i$success,
              na.rm = TRUE
            ),
          
          n_files_failed =
            sum(
              !file_status_i$success,
              na.rm = TRUE
            )
        )
      ]
    }
    
    
    # ========================================================
    # Successful site
    # ========================================================
    
    if (
      !is.null(era5_mean_i) &&
      nrow(era5_mean_i) > 0L
    ) {
      
      site_status[
        i,
        `:=`(
          success =
            TRUE,
          
          message =
            "OK"
        )
      ]
      
    } else {
      
      site_status[
        i,
        message :=
          "Single-site function completed but returned no ensemble-mean data."
      ]
    }
    
    
    # ========================================================
    # Free site-level objects before processing next site
    # ========================================================
    
    rm(
      result,
      metadata_i,
      era5_i,
      era5_mean_i,
      variable_info_i,
      file_status_i
    )
    
    
    gc(
      verbose = FALSE
    )
  }
  
  
  # ==========================================================
  # 8. Combine ensemble-mean data
  # ==========================================================
  
  valid_mean <- Filter(
    Negate(is.null),
    era5_mean_list
  )
  
  
  if (length(valid_mean) == 0L) {
    
    stop(
      "No valid ERA5 ensemble-mean data were obtained for any site."
    )
  }
  
  
  era5_mean_all <- rbindlist(
    valid_mean,
    use.names = TRUE,
    fill = TRUE
  )
  
  
  setorder(
    era5_mean_all,
    index,
    time
  )
  
  
  # ==========================================================
  # 9. Combine member-level data when requested
  # ==========================================================
  
  if (combine_all_members) {
    
    valid_members <- Filter(
      Negate(is.null),
      era5_list
    )
    
    
    if (length(valid_members) > 0L) {
      
      era5_all <- rbindlist(
        valid_members,
        use.names = TRUE,
        fill = TRUE
      )
      
      
      setorder(
        era5_all,
        index,
        member,
        time
      )
      
    } else {
      
      era5_all <- data.table()
    }
    
  } else {
    
    era5_all <- NULL
  }
  
  
  # ==========================================================
  # 10. Combine variable metadata
  # ==========================================================
  
  valid_variable_info <- Filter(
    Negate(is.null),
    variable_info_list
  )
  
  
  if (length(valid_variable_info) > 0L) {
    
    variable_info_all <- rbindlist(
      valid_variable_info,
      use.names = TRUE,
      fill = TRUE
    )
    
    
    variable_info_all <- unique(
      variable_info_all
    )
    
    
    setorder(
      variable_info_all,
      index,
      variable
    )
    
  } else {
    
    variable_info_all <- data.table()
  }
  
  
  # ==========================================================
  # 11. Combine file-level status
  # ==========================================================
  
  valid_file_status <- Filter(
    Negate(is.null),
    file_status_list
  )
  
  
  if (length(valid_file_status) > 0L) {
    
    file_status_all <- rbindlist(
      valid_file_status,
      use.names = TRUE,
      fill = TRUE
    )
    
    
    setorder(
      file_status_all,
      index,
      member,
      source_year
    )
    
  } else {
    
    file_status_all <- data.table()
  }
  
  
  # ==========================================================
  # 12. Output file tag
  # ==========================================================
  
  date_tag <- paste0(
    start_date,
    "_to_",
    end_date
  )
  
  
  # ==========================================================
  # 13. Save combined ensemble-mean ERA5 data
  # ==========================================================
  
  mean_file <- file.path(
    output_dir,
    paste0(
      "ERA5_soil_calibration_ensemble_mean_ALL_",
      date_tag,
      ".csv"
    )
  )
  
  
  fwrite(
    era5_mean_all,
    mean_file
  )
  
  
  # ==========================================================
  # 14. Save optional combined member-level data
  # ==========================================================
  
  if (
    combine_all_members &&
    !is.null(era5_all) &&
    nrow(era5_all) > 0L
  ) {
    
    member_file <- file.path(
      output_dir,
      paste0(
        "ERA5_soil_calibration_all_members_ALL_",
        date_tag,
        ".csv"
      )
    )
    
    
    fwrite(
      era5_all,
      member_file
    )
  }
  
  
  # ==========================================================
  # 15. Save metadata and status tables
  # ==========================================================
  
  variable_file <- file.path(
    output_dir,
    paste0(
      "ERA5_soil_calibration_variable_info_ALL_",
      date_tag,
      ".csv"
    )
  )
  
  
  file_status_file <- file.path(
    output_dir,
    paste0(
      "ERA5_soil_calibration_file_status_ALL_",
      date_tag,
      ".csv"
    )
  )
  
  
  site_status_file <- file.path(
    output_dir,
    paste0(
      "ERA5_soil_calibration_site_status_ALL_",
      date_tag,
      ".csv"
    )
  )
  
  
  if (nrow(variable_info_all) > 0L) {
    
    fwrite(
      variable_info_all,
      variable_file
    )
  }
  
  
  if (nrow(file_status_all) > 0L) {
    
    fwrite(
      file_status_all,
      file_status_file
    )
  }
  
  
  fwrite(
    site_status,
    site_status_file
  )
  
  
  # ==========================================================
  # 16. Return object
  # ==========================================================
  
  result <- list(
    era5_mean =
      era5_mean_all,
    
    era5 =
      era5_all,
    
    variable_info =
      variable_info_all,
    
    file_status =
      file_status_all,
    
    site_status =
      site_status
  )
  
  
  # ==========================================================
  # 17. Save combined RDS
  # ==========================================================
  
  rds_file <- file.path(
    output_dir,
    paste0(
      "ERA5_soil_calibration_ALL_",
      date_tag,
      ".rds"
    )
  )
  
  
  saveRDS(
    result,
    rds_file,
    compress = FALSE
  )
  
  
  # ==========================================================
  # 18. Final summary
  # ==========================================================
  
  elapsed_minutes <- as.numeric(
    difftime(
      Sys.time(),
      total_start,
      units = "mins"
    )
  )
  
  
  cat(
    "\n\n============================================\n",
    "ALL-SITE ERA5 EXTRACTION FINISHED\n",
    "============================================\n",
    "Requested sites:             ",
    n_sites,
    "\n",
    
    "Successful sites:          ",
    sum(
      site_status$success
    ),
    "\n",
    
    "Failed sites:              ",
    sum(
      !site_status$success
    ),
    "\n\n",
    
    "Total ensemble-mean rows:  ",
    nrow(
      era5_mean_all
    ),
    "\n",
    
    "Successful ERA5 files:     ",
    if (nrow(file_status_all) > 0L) {
      sum(
        file_status_all$success,
        na.rm = TRUE
      )
    } else {
      0L
    },
    "\n",
    
    "Failed/missing ERA5 files: ",
    if (nrow(file_status_all) > 0L) {
      sum(
        !file_status_all$success,
        na.rm = TRUE
      )
    } else {
      0L
    },
    "\n",
    
    "Combined member data:      ",
    combine_all_members,
    "\n",
    
    "Elapsed:                   ",
    round(
      elapsed_minutes,
      2
    ),
    " minutes\n\n",
    
    "Combined RDS:\n",
    rds_file,
    "\n",
    
    "============================================\n",
    sep = ""
  )
  
  
  return(
    result
  )
}

suppressPackageStartupMessages({
  library(data.table)
})


# =============================================================================
# Shared helpers
# =============================================================================


#' Calculate the mean of finite values
#'
#' @param x Numeric vector.
#'
#' @return Numeric mean of finite values, or `NA_real_` if no finite values
#'   are available.
#'
#' @md
#' @keywords internal
#' @author Yang Gu
soilmoisture_mean_finite <- function(
    x
) {
  
  x <- suppressWarnings(
    as.numeric(
      x
    )
  )
  
  
  x <- x[
    is.finite(
      x
    )
  ]
  
  
  if (length(x) == 0L) {
    
    return(
      NA_real_
    )
  }
  
  
  return(
    mean(
      x
    )
  )
}


#' Calculate the standard deviation of finite values
#'
#' @param x Numeric vector.
#'
#' @return Numeric standard deviation of finite values, or `NA_real_` when
#'   fewer than two finite values are available.
#'
#' @md
#' @keywords internal
#' @author Yang Gu
soilmoisture_sd_finite <- function(
    x
) {
  
  x <- suppressWarnings(
    as.numeric(
      x
    )
  )
  
  
  x <- x[
    is.finite(
      x
    )
  ]
  
  
  if (length(x) < 2L) {
    
    return(
      NA_real_
    )
  }
  
  
  return(
    stats::sd(
      x
    )
  )
}


# =============================================================================
# NEON soil moisture
# =============================================================================


#' Extract 3-hour NEON soil moisture for one site
#'
#' Extracts volumetric soil water content from John Zobitz's processed NEON
#' environmental files for a single NEON site.
#'
#' Only monthly files overlapping the requested date range are read. Soil
#' moisture observations are retained separately for every available
#' `verticalPosition`. Measurements from different horizontal positions are
#' first averaged at each native timestamp and depth and are then aggregated
#' to exact 3-hour UTC intervals.
#'
#' @param neon_code Character NEON site code.
#' @param start_date First date to extract in `"YYYY-MM-DD"` format.
#' @param end_date Last date to extract in `"YYYY-MM-DD"` format. Inclusive.
#' @param env_dir Directory containing processed NEON environmental files named
#'   `env-meas-<SITE>-<YYYY-MM>.Rda`.
#' @param min_30min_per_3h Minimum number of native observations required to
#'   retain a 3-hour value. Default is 1.
#'
#' @return A data.table containing exact 3-hour UTC soil moisture observations
#'   for all available NEON vertical positions.
#'
#' @md
#' @keywords internal
#' @author Yang Gu
get_neon_soilmoisture_3h_single_site <- function(
    neon_code,
    start_date,
    end_date,
    env_dir =
      "/projectnb/dietzelab/jzobitz/02-NEON-sites/env-data",
    min_30min_per_3h = 1L
) {
  
  # ==========================================================================
  # 1. Requested time range
  # ==========================================================================
  
  start_time <- as.POSIXct(
    paste0(
      start_date,
      " 00:00:00"
    ),
    tz = "UTC"
  )
  
  
  end_time <- as.POSIXct(
    paste0(
      end_date,
      " 00:00:00"
    ),
    tz = "UTC"
  ) +
    86400
  
  
  if (
    is.na(start_time) ||
    is.na(end_time)
  ) {
    
    stop(
      "Dates must use YYYY-MM-DD.",
      call. = FALSE
    )
  }
  
  
  if (end_time <= start_time) {
    
    stop(
      "`end_date` must be >= `start_date`.",
      call. = FALSE
    )
  }
  
  
  # ==========================================================================
  # 2. Determine requested monthly files
  # ==========================================================================
  
  first_month <- as.Date(
    format(
      start_time,
      "%Y-%m-01",
      tz = "UTC"
    )
  )
  
  
  last_month <- as.Date(
    format(
      end_time - 1,
      "%Y-%m-01",
      tz = "UTC"
    )
  )
  
  
  month_sequence <- seq(
    first_month,
    last_month,
    by = "month"
  )
  
  
  env_files <- file.path(
    env_dir,
    paste0(
      "env-meas-",
      neon_code,
      "-",
      format(
        month_sequence,
        "%Y-%m"
      ),
      ".Rda"
    )
  )
  
  
  env_files <- env_files[
    file.exists(
      env_files
    )
  ]
  
  
  if (length(env_files) == 0L) {
    
    warning(
      "No NEON environmental files found for ",
      neon_code,
      " in the requested date range.",
      call. = FALSE
    )
    
    return(
      NULL
    )
  }
  
  
  # ==========================================================================
  # 3. Read one monthly NEON file
  # ==========================================================================
  
  read_one_file <- function(
    file_i
  ) {
    
    env_i <- new.env(
      parent =
        emptyenv()
    )
    
    
    load(
      file_i,
      envir =
        env_i
    )
    
    
    if (
      !exists(
        "site_data",
        envir = env_i,
        inherits = FALSE
      )
    ) {
      
      return(
        NULL
      )
    }
    
    
    site_data <- get(
      "site_data",
      envir = env_i,
      inherits = FALSE
    )
    
    
    # ------------------------------------------------------------------------
    # John Zobitz NEON structure:
    #
    # site_data level 2 -> environmental measurements
    # soil-moisture element -> VSWC observations
    # ------------------------------------------------------------------------
    
    environmental_data <- tryCatch(
      getElement(
        site_data,
        2L
      ),
      error = function(e) {
        NULL
      }
    )
    
    
    if (is.null(environmental_data)) {
      
      return(
        NULL
      )
    }
    
    
    soil_moisture_raw <- tryCatch(
      getElement(
        environmental_data,
        2L
      ),
      error = function(e) {
        NULL
      }
    )
    
    
    if (is.null(soil_moisture_raw)) {
      
      return(
        NULL
      )
    }
    
    
    soil_moisture <- tryCatch(
      data.table::as.data.table(
        soil_moisture_raw
      ),
      error = function(e) {
        NULL
      }
    )
    
    
    if (
      is.null(soil_moisture) ||
      nrow(soil_moisture) == 0L
    ) {
      
      return(
        NULL
      )
    }
    
    
    # =========================================================================
    # 4. Check required columns
    # =========================================================================
    
    required_columns <- c(
      "startDateTime",
      "horizontalPosition",
      "verticalPosition",
      "VSWCMean"
    )
    
    
    missing_columns <- setdiff(
      required_columns,
      names(
        soil_moisture
      )
    )
    
    
    if (length(missing_columns) > 0L) {
      
      warning(
        "Missing columns in ",
        basename(
          file_i
        ),
        ": ",
        paste(
          missing_columns,
          collapse = ", "
        ),
        call. = FALSE
      )
      
      return(
        NULL
      )
    }
    
    
    # =========================================================================
    # 5. Clean observations
    # =========================================================================
    
    soil_moisture[
      ,
      time :=
        as.POSIXct(
          startDateTime,
          tz = "UTC"
        )
    ]
    
    
    soil_moisture[
      ,
      VSWCMean :=
        suppressWarnings(
          as.numeric(
            VSWCMean
          )
        )
    ]
    
    
    soil_moisture[
      ,
      verticalPosition :=
        as.character(
          verticalPosition
        )
    ]
    
    
    soil_moisture[
      ,
      horizontalPosition :=
        as.character(
          horizontalPosition
        )
    ]
    
    
    if (
      "zOffset" %in%
      names(
        soil_moisture
      )
    ) {
      
      soil_moisture[
        ,
        zOffset_m :=
          suppressWarnings(
            as.numeric(
              zOffset
            )
          )
      ]
      
    } else {
      
      soil_moisture[
        ,
        zOffset_m :=
          NA_real_
      ]
    }
    
    
    soil_moisture <- soil_moisture[
      !is.na(
        time
      ) &
        time >=
        start_time &
        time <
        end_time &
        !is.na(
          verticalPosition
        ) &
        verticalPosition !=
        "" &
        is.finite(
          VSWCMean
        )
    ]
    
    
    if (nrow(soil_moisture) == 0L) {
      
      return(
        NULL
      )
    }
    
    
    # =========================================================================
    # 6. Average horizontal positions
    #
    # One value per:
    #
    # time x verticalPosition
    #
    # Depths remain separate.
    # =========================================================================
    
    soil_30min <- soil_moisture[
      ,
      .(
        VSWC =
          mean(
            VSWCMean,
            na.rm = TRUE
          ),
        
        VSWC_spatial_sd =
          soilmoisture_sd_finite(
            VSWCMean
          ),
        
        mean_zOffset_m =
          soilmoisture_mean_finite(
            zOffset_m
          ),
        
        n_position =
          data.table::uniqueN(
            horizontalPosition
          )
      ),
      by = .(
        time,
        verticalPosition
      )
    ]
    
    
    return(
      soil_30min
    )
  }
  
  
  # ==========================================================================
  # 7. Read requested months
  # ==========================================================================
  
  monthly_list <- lapply(
    env_files,
    read_one_file
  )
  
  
  monthly_list <- Filter(
    Negate(
      is.null
    ),
    monthly_list
  )
  
  
  if (length(monthly_list) == 0L) {
    
    warning(
      "No valid NEON soil moisture observations found for ",
      neon_code,
      ".",
      call. = FALSE
    )
    
    return(
      NULL
    )
  }
  
  
  soil_30min <- data.table::rbindlist(
    monthly_list,
    use.names = TRUE,
    fill = TRUE
  )
  
  
  # ==========================================================================
  # 8. Protect against month-boundary duplicates
  # ==========================================================================
  
  soil_30min <- soil_30min[
    ,
    .(
      VSWC =
        mean(
          VSWC,
          na.rm = TRUE
        ),
      
      VSWC_spatial_sd =
        soilmoisture_mean_finite(
          VSWC_spatial_sd
        ),
      
      mean_zOffset_m =
        soilmoisture_mean_finite(
          mean_zOffset_m
        ),
      
      n_position =
        max(
          n_position,
          na.rm = TRUE
        )
    ),
    by = .(
      time,
      verticalPosition
    )
  ]
  
  
  # ==========================================================================
  # 9. Assign exact 3-hour UTC bins
  # ==========================================================================
  
  soil_30min[
    ,
    time_3h :=
      as.POSIXct(
        floor(
          as.numeric(
            time
          ) /
            10800
        ) *
          10800,
        origin = "1970-01-01",
        tz = "UTC"
      )
  ]
  
  
  # ==========================================================================
  # 10. Aggregate NEON data to 3 hours
  # ==========================================================================
  
  soil_3h <- soil_30min[
    ,
    .(
      VSWC_NEON =
        mean(
          VSWC,
          na.rm = TRUE
        ),
      
      VSWC_NEON_temporal_sd =
        soilmoisture_sd_finite(
          VSWC
        ),
      
      VSWC_NEON_spatial_sd =
        soilmoisture_mean_finite(
          VSWC_spatial_sd
        ),
      
      mean_zOffset_m =
        soilmoisture_mean_finite(
          mean_zOffset_m
        ),
      
      n_NEON_30min =
        .N,
      
      mean_NEON_positions =
        mean(
          n_position,
          na.rm = TRUE
        )
    ),
    by = .(
      time =
        time_3h,
      
      verticalPosition
    )
  ]
  
  
  soil_3h <- soil_3h[
    n_NEON_30min >=
      as.integer(
        min_30min_per_3h
      )
  ]
  
  
  soil_3h[
    ,
    NEON_code :=
      neon_code
  ]
  
  
  data.table::setorder(
    soil_3h,
    verticalPosition,
    time
  )
  
  
  return(
    soil_3h
  )
}


# =============================================================================
# SIPNET soil moisture
# =============================================================================


#' Extract 3-hour SIPNET soil moisture for one model site
#'
#' Reads `soilWater` and `soilWetnessFrac` from every SIPNET ensemble for a
#' single model-site index and calculates ensemble statistics at exact 3-hour
#' UTC timestamps.
#'
#' SIPNET time values may contain floating-point drift. The first model
#' timestamp is therefore used only to establish the time origin, and all
#' subsequent timestamps are reconstructed from row order at exact 3-hour
#' intervals.
#'
#' @param index Integer model-site index.
#' @param start_date First date to extract in `"YYYY-MM-DD"` format.
#' @param end_date Last date to extract in `"YYYY-MM-DD"` format. Inclusive.
#' @param out_dir Directory containing SIPNET ensemble directories named
#'   `ENS-<ensemble>-<index>`.
#'
#' @return A data.table containing exact 3-hour ensemble-mean `soilWater` and
#'   `soilWetnessFrac`.
#'
#' @md
#' @keywords internal
#' @author Yang Gu
get_sipnet_soilmoisture_3h_single_site <- function(
    index,
    start_date,
    end_date,
    out_dir =
      "/projectnb/dietzelab/guYANG/pecan/updated_clim/out"
) {
  
  site_index <- as.integer(
    index
  )
  
  
  start_time <- as.POSIXct(
    paste0(
      start_date,
      " 00:00:00"
    ),
    tz = "UTC"
  )
  
  
  end_time <- as.POSIXct(
    paste0(
      end_date,
      " 00:00:00"
    ),
    tz = "UTC"
  ) +
    86400
  
  
  # ==========================================================================
  # 1. Find SIPNET ensembles
  # ==========================================================================
  
  ensemble_dirs <- list.dirs(
    out_dir,
    recursive = FALSE,
    full.names = TRUE
  )
  
  
  directory_pattern <- paste0(
    "^ENS-[0-9]+-",
    site_index,
    "$"
  )
  
  
  ensemble_dirs <- ensemble_dirs[
    grepl(
      directory_pattern,
      basename(
        ensemble_dirs
      )
    )
  ]
  
  
  if (length(ensemble_dirs) == 0L) {
    
    warning(
      "No SIPNET ensemble directories found for index ",
      site_index,
      ".",
      call. = FALSE
    )
    
    return(
      NULL
    )
  }
  
  
  # ==========================================================================
  # 2. Read one ensemble
  # ==========================================================================
  
  read_one_ensemble <- function(
    ensemble_dir
  ) {
    
    sipnet_file <- file.path(
      ensemble_dir,
      "sipnet.out"
    )
    
    
    if (!file.exists(sipnet_file)) {
      
      return(
        NULL
      )
    }
    
    
    header <- tryCatch(
      names(
        data.table::fread(
          sipnet_file,
          nrows = 0L,
          showProgress = FALSE
        )
      ),
      error = function(e) {
        character()
      }
    )
    
    
    if (length(header) == 0L) {
      
      return(
        NULL
      )
    }
    
    
    header_lower <- tolower(
      header
    )
    
    
    year_column <- header[
      header_lower ==
        "year"
    ]
    
    
    day_column <- header[
      header_lower %in%
        c(
          "day",
          "doy"
        )
    ]
    
    
    time_column <- header[
      header_lower ==
        "time"
    ]
    
    
    soilwater_column <- header[
      header_lower ==
        "soilwater"
    ]
    
    
    wetness_column <- header[
      header_lower ==
        "soilwetnessfrac"
    ]
    
    
    if (
      length(year_column) != 1L ||
      length(day_column) != 1L ||
      length(time_column) != 1L ||
      length(soilwater_column) != 1L ||
      length(wetness_column) != 1L
    ) {
      
      warning(
        "Required soil-moisture columns were not found in ",
        sipnet_file,
        ".",
        call. = FALSE
      )
      
      return(
        NULL
      )
    }
    
    
    x <- tryCatch(
      data.table::fread(
        sipnet_file,
        select = c(
          year_column,
          day_column,
          time_column,
          soilwater_column,
          wetness_column
        ),
        showProgress = FALSE
      ),
      error = function(e) {
        NULL
      }
    )
    
    
    if (
      is.null(x) ||
      nrow(x) == 0L
    ) {
      
      return(
        NULL
      )
    }
    
    
    data.table::setnames(
      x,
      old = c(
        year_column,
        day_column,
        time_column,
        soilwater_column,
        wetness_column
      ),
      new = c(
        "year_raw",
        "doy_raw",
        "hour_raw",
        "soilWater",
        "soilWetnessFrac"
      )
    )
    
    
    x[
      ,
      `:=`(
        year_raw =
          as.integer(
            year_raw
          ),
        
        doy_raw =
          as.numeric(
            doy_raw
          ),
        
        hour_raw =
          as.numeric(
            hour_raw
          ),
        
        soilWater =
          as.numeric(
            soilWater
          ),
        
        soilWetnessFrac =
          as.numeric(
            soilWetnessFrac
          )
      )
    ]
    
    
    # =========================================================================
    # 3. Exact 3-hour time reconstruction
    #
    # Use only the first model timestamp.
    # Subsequent timestamps are generated from row order.
    # =========================================================================
    
    first_hour_exact <- round(
      x$hour_raw[1L] /
        3
    ) *
      3
    
    
    first_datetime <- as.POSIXct(
      sprintf(
        "%04d-01-01 00:00:00",
        x$year_raw[1L]
      ),
      tz = "UTC"
    ) +
      (
        x$doy_raw[1L] -
          1
      ) *
      86400 +
      first_hour_exact *
      3600
    
    
    x[
      ,
      time :=
        first_datetime +
        (
          seq_len(
            .N
          ) -
            1L
        ) *
        10800
    ]
    
    
    x <- x[
      time >=
        start_time &
        time <
        end_time
    ]
    
    
    if (nrow(x) == 0L) {
      
      return(
        NULL
      )
    }
    
    
    ensemble_id <- as.integer(
      sub(
        "^ENS-([0-9]+)-.*$",
        "\\1",
        basename(
          ensemble_dir
        )
      )
    )
    
    
    x[
      ,
      ensemble :=
        ensemble_id
    ]
    
    
    return(
      x[
        ,
        .(
          time,
          ensemble,
          soilWater,
          soilWetnessFrac
        )
      ]
    )
  }
  
  
  # ==========================================================================
  # 4. Read all ensembles
  # ==========================================================================
  
  ensemble_list <- lapply(
    ensemble_dirs,
    read_one_ensemble
  )
  
  
  ensemble_list <- Filter(
    Negate(
      is.null
    ),
    ensemble_list
  )
  
  
  if (length(ensemble_list) == 0L) {
    
    warning(
      "No valid SIPNET soil-moisture output found for index ",
      site_index,
      ".",
      call. = FALSE
    )
    
    return(
      NULL
    )
  }
  
  
  all_ensembles <- data.table::rbindlist(
    ensemble_list,
    use.names = TRUE,
    fill = TRUE
  )
  
  
  # ==========================================================================
  # 5. Ensemble statistics
  # ==========================================================================
  
  result <- all_ensembles[
    ,
    .(
      SoilWater_SIPNET =
        soilmoisture_mean_finite(
          soilWater
        ),
      
      SoilWater_SIPNET_sd =
        soilmoisture_sd_finite(
          soilWater
        ),
      
      SoilWetnessFrac_SIPNET =
        soilmoisture_mean_finite(
          soilWetnessFrac
        ),
      
      SoilWetnessFrac_SIPNET_sd =
        soilmoisture_sd_finite(
          soilWetnessFrac
        ),
      
      n_ensemble =
        data.table::uniqueN(
          ensemble[
            is.finite(
              soilWetnessFrac
            )
          ]
        )
    ),
    by =
      time
  ]
  
  
  result[
    ,
    index :=
      site_index
  ]
  
  
  data.table::setcolorder(
    result,
    c(
      "time",
      "index",
      "SoilWater_SIPNET",
      "SoilWater_SIPNET_sd",
      "SoilWetnessFrac_SIPNET",
      "SoilWetnessFrac_SIPNET_sd",
      "n_ensemble"
    )
  )
  
  
  data.table::setorder(
    result,
    time
  )
  
  
  return(
    result
  )
}


suppressPackageStartupMessages({
  library(data.table)
})


#' Prepare NEON and SIPNET soil-moisture validation data
#'
#' Creates a matched 3-hour soil-moisture validation table for all requested
#' model sites using previously extracted NEON observations and ERA5
#' meteorological forcing.
#'
#' NEON observations are taken directly from
#' `multi_site$soilMoisture`, which contains 3-hour volumetric soil water
#' content for all available NEON soil depths.
#'
#' ERA5 meteorological forcing is taken directly from
#' `era5_all$era5_mean`. ERA5 is not used as a soil-moisture observation;
#' instead, it supplies the common exact 3-hour meteorological timeline and
#' environmental drivers associated with each soil-moisture comparison.
#'
#' SIPNET soil moisture is read from `sipnet.out` for all ensemble members at
#' each model-site index. `soilWater` and `soilWetnessFrac` are extracted and
#' averaged across ensembles at each exact 3-hour UTC timestep.
#'
#' Because SIPNET represents soil moisture as one effective site-level soil
#' water state, the same SIPNET soil-moisture estimate is compared separately
#' against every available NEON `verticalPosition`.
#'
#' @md
#' @param lookup A data.frame or data.table containing model-site metadata.
#'   Must contain `index`. `AmeriFlux_ID`, `NEON_code`, and `NEON_name` are
#'   retained when available.
#' @param multi_site Object returned by `get_soil_neon_data_multi_site()`.
#'   Must contain `soilMoisture`.
#' @param era5_all Object returned by `get_soil_era5_data_multi_site()`.
#'   Must contain `era5_mean`.
#' @param start_date Character string giving the first comparison date in
#'   `"YYYY-MM-DD"` format. Inclusive.
#' @param end_date Character string giving the final comparison date in
#'   `"YYYY-MM-DD"` format. Inclusive.
#' @param sipnet_out_dir Directory containing SIPNET ensemble output folders
#'   named `ENS-<ensemble>-<index>`.
#' @param output_file Optional path for the combined validation CSV. If `NULL`,
#'   no file is written.
#' @param keep_only_paired Logical. If `TRUE`, only timestamps containing both
#'   NEON VSWC and SIPNET `soilWetnessFrac` are retained. Default is `TRUE`.
#' @param include_era5_drivers Logical. If `TRUE`, selected ERA5 meteorological
#'   drivers are included in the returned table. Default is `TRUE`.
#'
#' @return A data.table with one row per model-site index, NEON soil depth, and
#'   exact 3-hour UTC timestamp. Primary comparison variables are
#'   `VSWC_NEON` and `SoilWetnessFrac_SIPNET`.
#'
#' @export
#' @author Yang Gu
prepare_soilmoisture_validation_table <- function(
    lookup,
    multi_site,
    era5_all,
    start_date,
    end_date,
    sipnet_out_dir =
      "/projectnb/dietzelab/guYANG/pecan/updated_clim/out",
    output_file =
      "/projectnb/dietzelab/guYANG/soilparam/SoilMoisture_validation/NEON_SIPNET_SoilMoisture_3hour.csv",
    keep_only_paired = TRUE,
    include_era5_drivers = TRUE
) {
  
  # ==========================================================================
  # 1. Validate prepared input objects
  # ==========================================================================
  
  neon_sm <- getElement(
    multi_site,
    "soilMoisture"
  )
  
  
  era5_mean <- getElement(
    era5_all,
    "era5_mean"
  )
  
  
  if (
    is.null(neon_sm) ||
    nrow(neon_sm) == 0L
  ) {
    
    stop(
      "`multi_site` does not contain valid `soilMoisture` data.",
      call. = FALSE
    )
  }
  
  
  if (
    is.null(era5_mean) ||
    nrow(era5_mean) == 0L
  ) {
    
    stop(
      "`era5_all` does not contain valid `era5_mean` data.",
      call. = FALSE
    )
  }
  
  
  neon_sm <- data.table::as.data.table(
    data.table::copy(
      neon_sm
    )
  )
  
  
  era5_mean <- data.table::as.data.table(
    data.table::copy(
      era5_mean
    )
  )
  
  
  lookup_dt <- data.table::as.data.table(
    data.table::copy(
      lookup
    )
  )
  
  
  # ==========================================================================
  # 2. Validate required columns
  # ==========================================================================
  
  required_neon_columns <- c(
    "time",
    "index",
    "verticalPosition",
    "VSWC"
  )
  
  
  missing_neon_columns <- setdiff(
    required_neon_columns,
    names(
      neon_sm
    )
  )
  
  
  if (length(missing_neon_columns) > 0L) {
    
    stop(
      "`multi_site$soilMoisture` is missing: ",
      paste(
        missing_neon_columns,
        collapse = ", "
      ),
      call. = FALSE
    )
  }
  
  
  required_era5_columns <- c(
    "time",
    "index"
  )
  
  
  missing_era5_columns <- setdiff(
    required_era5_columns,
    names(
      era5_mean
    )
  )
  
  
  if (length(missing_era5_columns) > 0L) {
    
    stop(
      "`era5_all$era5_mean` is missing: ",
      paste(
        missing_era5_columns,
        collapse = ", "
      ),
      call. = FALSE
    )
  }
  
  
  if (
    !"index" %in%
    names(
      lookup_dt
    )
  ) {
    
    stop(
      "`lookup` must contain `index`.",
      call. = FALSE
    )
  }
  
  
  # ==========================================================================
  # 3. Requested time range
  # ==========================================================================
  
  start_time <- as.POSIXct(
    paste0(
      start_date,
      " 00:00:00"
    ),
    tz = "UTC"
  )
  
  
  end_time <- as.POSIXct(
    paste0(
      end_date,
      " 00:00:00"
    ),
    tz = "UTC"
  ) +
    86400
  
  
  if (
    is.na(start_time) ||
    is.na(end_time)
  ) {
    
    stop(
      "Dates must use YYYY-MM-DD.",
      call. = FALSE
    )
  }
  
  
  if (end_time <= start_time) {
    
    stop(
      "`end_date` must be >= `start_date`.",
      call. = FALSE
    )
  }
  
  
  # ==========================================================================
  # 4. Determine requested model indices
  # ==========================================================================
  
  lookup_indices <- unique(
    as.integer(
      lookup_dt[
        !is.na(index),
        index
      ]
    )
  )
  
  
  lookup_indices <- lookup_indices[
    is.finite(
      lookup_indices
    )
  ]
  
  
  neon_indices <- unique(
    as.integer(
      neon_sm$index
    )
  )
  
  
  era5_indices <- unique(
    as.integer(
      era5_mean$index
    )
  )
  
  
  target_indices <- sort(
    Reduce(
      intersect,
      list(
        lookup_indices,
        neon_indices,
        era5_indices
      )
    )
  )
  
  
  if (length(target_indices) == 0L) {
    
    stop(
      paste0(
        "No common model indices were found among lookup, ",
        "multi_site, and era5_all."
      ),
      call. = FALSE
    )
  }
  
  
  # ==========================================================================
  # 5. Prepare NEON soil moisture
  # ==========================================================================
  
  neon_sm[
    ,
    time :=
      as.POSIXct(
        time,
        tz = "UTC"
      )
  ]
  
  
  neon_sm[
    ,
    index :=
      as.integer(
        index
      )
  ]
  
  
  neon_sm[
    ,
    verticalPosition :=
      as.character(
        verticalPosition
      )
  ]
  
  
  neon_sm <- neon_sm[
    index %in%
      target_indices &
      time >=
      start_time &
      time <
      end_time
  ]
  
  
  data.table::setnames(
    neon_sm,
    "VSWC",
    "VSWC_NEON"
  )
  
  
  if (
    "VSWC_temporal_sd" %in%
    names(
      neon_sm
    )
  ) {
    
    data.table::setnames(
      neon_sm,
      "VSWC_temporal_sd",
      "VSWC_NEON_temporal_sd"
    )
  }
  
  
  if (
    "VSWC_spatial_sd" %in%
    names(
      neon_sm
    )
  ) {
    
    data.table::setnames(
      neon_sm,
      "VSWC_spatial_sd",
      "VSWC_NEON_spatial_sd"
    )
  }
  
  
  # ==========================================================================
  # 6. Prepare ERA5 exact-time meteorological table
  # ==========================================================================
  
  era5_mean[
    ,
    time :=
      as.POSIXct(
        time,
        tz = "UTC"
      )
  ]
  
  
  era5_mean[
    ,
    index :=
      as.integer(
        index
      )
  ]
  
  
  era5_mean <- era5_mean[
    index %in%
      target_indices &
      time >=
      start_time &
      time <
      end_time
  ]
  
  
  # --------------------------------------------------------------------------
  # Keep only one ERA5 record per index and exact timestamp
  # --------------------------------------------------------------------------
  
  era5_mean <- unique(
    era5_mean,
    by = c(
      "index",
      "time"
    )
  )
  
  
  # ==========================================================================
  # 7. Helper functions for SIPNET extraction
  # ==========================================================================
  
  mean_finite <- function(
    x
  ) {
    
    x <- suppressWarnings(
      as.numeric(
        x
      )
    )
    
    
    x <- x[
      is.finite(
        x
      )
    ]
    
    
    if (length(x) == 0L) {
      
      return(
        NA_real_
      )
    }
    
    
    return(
      mean(
        x
      )
    )
  }
  
  
  sd_finite <- function(
    x
  ) {
    
    x <- suppressWarnings(
      as.numeric(
        x
      )
    )
    
    
    x <- x[
      is.finite(
        x
      )
    ]
    
    
    if (length(x) < 2L) {
      
      return(
        NA_real_
      )
    }
    
    
    return(
      stats::sd(
        x
      )
    )
  }
  
  
  # ==========================================================================
  # 8. Find SIPNET ensemble directories once
  # ==========================================================================
  
  all_ensemble_dirs <- list.dirs(
    sipnet_out_dir,
    recursive = FALSE,
    full.names = TRUE
  )
  
  
  if (length(all_ensemble_dirs) == 0L) {
    
    stop(
      "No SIPNET ensemble directories were found in: ",
      sipnet_out_dir,
      call. = FALSE
    )
  }
  
  
  # ==========================================================================
  # 9. Extract SIPNET soil moisture for one index
  # ==========================================================================
  
  read_sipnet_index <- function(
    index_i
  ) {
    
    directory_pattern <- paste0(
      "^ENS-[0-9]+-",
      index_i,
      "$"
    )
    
    
    ensemble_dirs <- all_ensemble_dirs[
      grepl(
        directory_pattern,
        basename(
          all_ensemble_dirs
        )
      )
    ]
    
    
    if (length(ensemble_dirs) == 0L) {
      
      return(
        NULL
      )
    }
    
    
    ensemble_data <- vector(
      "list",
      length(
        ensemble_dirs
      )
    )
    
    
    for (
      ensemble_i in
      seq_along(
        ensemble_dirs
      )
    ) {
      
      ensemble_dir <- ensemble_dirs[
        ensemble_i
      ]
      
      
      sipnet_file <- file.path(
        ensemble_dir,
        "sipnet.out"
      )
      
      
      if (!file.exists(sipnet_file)) {
        
        next
      }
      
      
      # -----------------------------------------------------------------------
      # Read header to identify SIPNET columns
      # -----------------------------------------------------------------------
      
      header <- tryCatch(
        names(
          data.table::fread(
            sipnet_file,
            nrows = 0L,
            showProgress = FALSE
          )
        ),
        error = function(e) {
          character()
        }
      )
      
      
      if (length(header) == 0L) {
        
        next
      }
      
      
      header_lower <- tolower(
        header
      )
      
      
      year_column <- header[
        header_lower ==
          "year"
      ]
      
      
      day_column <- header[
        header_lower %in%
          c(
            "day",
            "doy"
          )
      ]
      
      
      time_column <- header[
        header_lower ==
          "time"
      ]
      
      
      soilwater_column <- header[
        header_lower ==
          "soilwater"
      ]
      
      
      wetness_column <- header[
        header_lower ==
          "soilwetnessfrac"
      ]
      
      
      if (
        length(year_column) != 1L ||
        length(day_column) != 1L ||
        length(time_column) != 1L ||
        length(soilwater_column) != 1L ||
        length(wetness_column) != 1L
      ) {
        
        next
      }
      
      
      # -----------------------------------------------------------------------
      # Read only required variables
      # -----------------------------------------------------------------------
      
      x <- tryCatch(
        data.table::fread(
          sipnet_file,
          select = c(
            year_column,
            day_column,
            time_column,
            soilwater_column,
            wetness_column
          ),
          showProgress = FALSE
        ),
        error = function(e) {
          NULL
        }
      )
      
      
      if (
        is.null(x) ||
        nrow(x) == 0L
      ) {
        
        next
      }
      
      
      data.table::setnames(
        x,
        old = c(
          year_column,
          day_column,
          time_column,
          soilwater_column,
          wetness_column
        ),
        new = c(
          "year_raw",
          "doy_raw",
          "hour_raw",
          "soilWater",
          "soilWetnessFrac"
        )
      )
      
      
      x[
        ,
        `:=`(
          year_raw =
            as.integer(
              year_raw
            ),
          
          doy_raw =
            as.numeric(
              doy_raw
            ),
          
          hour_raw =
            as.numeric(
              hour_raw
            ),
          
          soilWater =
            as.numeric(
              soilWater
            ),
          
          soilWetnessFrac =
            as.numeric(
              soilWetnessFrac
            )
        )
      ]
      
      
      # -----------------------------------------------------------------------
      # Reconstruct exact 3-hour SIPNET time
      #
      # SIPNET floating-point time is used only for the first timestamp.
      # Every later timestamp follows exact row order at 3-hour intervals.
      # -----------------------------------------------------------------------
      
      first_hour_exact <- round(
        x$hour_raw[1L] /
          3
      ) *
        3
      
      
      first_datetime <- as.POSIXct(
        sprintf(
          "%04d-01-01 00:00:00",
          x$year_raw[1L]
        ),
        tz = "UTC"
      ) +
        (
          x$doy_raw[1L] -
            1
        ) *
        86400 +
        first_hour_exact *
        3600
      
      
      x[
        ,
        time :=
          first_datetime +
          (
            seq_len(
              .N
            ) -
              1L
          ) *
          10800
      ]
      
      
      x <- x[
        time >=
          start_time &
          time <
          end_time
      ]
      
      
      if (nrow(x) == 0L) {
        
        next
      }
      
      
      ensemble_number <- as.integer(
        sub(
          "^ENS-([0-9]+)-.*$",
          "\\1",
          basename(
            ensemble_dir
          )
        )
      )
      
      
      x[
        ,
        ensemble :=
          ensemble_number
      ]
      
      
      ensemble_data[
        ensemble_i
      ] <- list(
        x[
          ,
          .(
            time,
            ensemble,
            soilWater,
            soilWetnessFrac
          )
        ]
      )
    }
    
    
    valid_ensemble_data <- Filter(
      Negate(
        is.null
      ),
      ensemble_data
    )
    
    
    if (length(valid_ensemble_data) == 0L) {
      
      return(
        NULL
      )
    }
    
    
    all_members <- data.table::rbindlist(
      valid_ensemble_data,
      use.names = TRUE,
      fill = TRUE
    )
    
    
    # -------------------------------------------------------------------------
    # Ensemble mean at every exact 3-hour timestep
    # -------------------------------------------------------------------------
    
    sipnet_mean <- all_members[
      ,
      .(
        SoilWater_SIPNET =
          mean_finite(
            soilWater
          ),
        
        SoilWater_SIPNET_sd =
          sd_finite(
            soilWater
          ),
        
        SoilWetnessFrac_SIPNET =
          mean_finite(
            soilWetnessFrac
          ),
        
        SoilWetnessFrac_SIPNET_sd =
          sd_finite(
            soilWetnessFrac
          ),
        
        n_SIPNET_ensemble =
          data.table::uniqueN(
            ensemble
          )
      ),
      by =
        time
    ]
    
    
    sipnet_mean[
      ,
      index :=
        as.integer(
          index_i
        )
    ]
    
    
    data.table::setorder(
      sipnet_mean,
      time
    )
    
    
    return(
      sipnet_mean
    )
  }
  
  
  # ==========================================================================
  # 10. Extract SIPNET soil moisture for all requested indices
  # ==========================================================================
  
  sipnet_list <- vector(
    "list",
    length(
      target_indices
    )
  )
  
  
  status <- data.table::data.table(
    index =
      target_indices,
    
    sipnet_success =
      FALSE,
    
    n_sipnet_time =
      0L
  )
  
  
  for (
    site_i in
    seq_along(
      target_indices
    )
  ) {
    
    index_i <- target_indices[
      site_i
    ]
    
    
    message(
      "[",
      site_i,
      "/",
      length(
        target_indices
      ),
      "] SIPNET soil moisture | index = ",
      index_i
    )
    
    
    sipnet_i <- read_sipnet_index(
      index_i
    )
    
    
    if (
      is.null(sipnet_i) ||
      nrow(sipnet_i) == 0L
    ) {
      
      next
    }
    
    
    sipnet_list[
      site_i
    ] <- list(
      sipnet_i
    )
    
    
    status[
      site_i,
      `:=`(
        sipnet_success =
          TRUE,
        
        n_sipnet_time =
          nrow(
            sipnet_i
          )
      )
    ]
  }
  
  
  valid_sipnet <- Filter(
    Negate(
      is.null
    ),
    sipnet_list
  )
  
  
  if (length(valid_sipnet) == 0L) {
    
    stop(
      "No valid SIPNET soil-moisture output was found.",
      call. = FALSE
    )
  }
  
  
  sipnet_sm <- data.table::rbindlist(
    valid_sipnet,
    use.names = TRUE,
    fill = TRUE
  )
  
  
  # ==========================================================================
  # 11. Match SIPNET to NEON observations
  #
  # NEON remains the base table because it contains multiple soil depths.
  # ==========================================================================
  
  comparison <- merge(
    neon_sm,
    sipnet_sm,
    by = c(
      "index",
      "time"
    ),
    all.x = TRUE,
    sort = FALSE
  )
  
  
  # ==========================================================================
  # 12. Add selected ERA5 drivers
  # ==========================================================================
  
  if (
    isTRUE(
      include_era5_drivers
    )
  ) {
    
    era5_driver_columns <- intersect(
      c(
        "index",
        "time",
        "AirT_C",
        "Precip_mm_3h",
        "VPD_Pa",
        "RH",
        "WindSpeed",
        "PAR_umol_m2_s",
        "surface_downwelling_shortwave_flux_in_air",
        "surface_downwelling_longwave_flux_in_air"
      ),
      names(
        era5_mean
      )
    )
    
    
    era5_for_join <- era5_mean[
      ,
      ..era5_driver_columns
    ]
    
    
    comparison <- merge(
      comparison,
      era5_for_join,
      by = c(
        "index",
        "time"
      ),
      all.x = TRUE,
      sort = FALSE
    )
  }
  
  
  # ==========================================================================
  # 13. Add paired-data flag
  # ==========================================================================
  
  comparison[
    ,
    paired :=
      is.finite(
        VSWC_NEON
      ) &
      is.finite(
        SoilWetnessFrac_SIPNET
      )
  ]
  
  
  comparison[
    ,
    n_paired_site_depth :=
      sum(
        paired,
        na.rm = TRUE
      ),
    by = .(
      index,
      verticalPosition
    )
  ]
  
  
  # ==========================================================================
  # 14. Standardize moisture dynamics within each site and depth
  #
  # Raw NEON VSWC and SIPNET soilWetnessFrac are not identical physical
  # quantities, so standardized values are useful for dynamics validation.
  # ==========================================================================
  
  comparison[
    ,
    `:=`(
      VSWC_NEON_z =
        NA_real_,
      
      SoilWetnessFrac_SIPNET_z =
        NA_real_
    )
  ]
  
  
  comparison[
    paired == TRUE,
    VSWC_NEON_z := {
      
      x <- VSWC_NEON
      
      
      x_sd <- stats::sd(
        x
      )
      
      
      if (
        .N >= 3L &&
        is.finite(x_sd) &&
        x_sd > 0
      ) {
        
        (
          x -
            mean(
              x
            )
        ) /
          x_sd
        
      } else {
        
        rep(
          NA_real_,
          .N
        )
      }
    },
    by = .(
      index,
      verticalPosition
    )
  ]
  
  
  comparison[
    paired == TRUE,
    SoilWetnessFrac_SIPNET_z := {
      
      x <- SoilWetnessFrac_SIPNET
      
      
      x_sd <- stats::sd(
        x
      )
      
      
      if (
        .N >= 3L &&
        is.finite(x_sd) &&
        x_sd > 0
      ) {
        
        (
          x -
            mean(
              x
            )
        ) /
          x_sd
        
      } else {
        
        rep(
          NA_real_,
          .N
        )
      }
    },
    by = .(
      index,
      verticalPosition
    )
  ]
  
  
  # ==========================================================================
  # 15. Keep paired timestamps if requested
  # ==========================================================================
  
  if (
    isTRUE(
      keep_only_paired
    )
  ) {
    
    comparison <- comparison[
      paired == TRUE
    ]
  }
  
  
  # ==========================================================================
  # 16. Final column order
  # ==========================================================================
  
  preferred_columns <- c(
    "time",
    "index",
    "AmeriFlux_ID",
    "NEON_code",
    "NEON_name",
    "verticalPosition",
    "mean_zOffset",
    
    "VSWC_NEON",
    "SoilWetnessFrac_SIPNET",
    "SoilWater_SIPNET",
    
    "VSWC_NEON_z",
    "SoilWetnessFrac_SIPNET_z",
    
    "VSWC_NEON_temporal_sd",
    "VSWC_NEON_spatial_sd",
    
    "SoilWetnessFrac_SIPNET_sd",
    "SoilWater_SIPNET_sd",
    
    "n_30min",
    "mean_n_position",
    "n_SIPNET_ensemble",
    "n_paired_site_depth",
    
    "AirT_C",
    "Precip_mm_3h",
    "VPD_Pa",
    "RH",
    "WindSpeed",
    "PAR_umol_m2_s",
    
    "paired"
  )
  
  
  preferred_columns <- intersect(
    preferred_columns,
    names(
      comparison
    )
  )
  
  
  data.table::setcolorder(
    comparison,
    c(
      preferred_columns,
      setdiff(
        names(
          comparison
        ),
        preferred_columns
      )
    )
  )
  
  
  data.table::setorder(
    comparison,
    index,
    verticalPosition,
    time
  )
  
  
  # ==========================================================================
  # 17. Save
  # ==========================================================================
  
  if (!is.null(output_file)) {
    
    dir.create(
      dirname(
        output_file
      ),
      recursive = TRUE,
      showWarnings = FALSE
    )
    
    
    data.table::fwrite(
      comparison,
      output_file
    )
    
    
    status_file <- sub(
      "\\.csv$",
      "_status.csv",
      output_file
    )
    
    
    data.table::fwrite(
      status,
      status_file
    )
  }
  
  
  # ==========================================================================
  # 18. Summary
  # ==========================================================================
  
  cat(
    "\n============================================\n",
    "SOIL MOISTURE VALIDATION TABLE\n",
    "============================================\n",
    "Requested indices:       ",
    length(
      target_indices
    ),
    "\n",
    
    "SIPNET indices found:   ",
    sum(
      status$sipnet_success
    ),
    "\n",
    
    "NEON site-depth pairs:  ",
    data.table::uniqueN(
      paste(
        comparison$index,
        comparison$verticalPosition
      )
    ),
    "\n",
    
    "Paired 3-hour rows:     ",
    sum(
      comparison$paired,
      na.rm = TRUE
    ),
    "\n",
    
    "Date range:             ",
    start_date,
    " to ",
    end_date,
    "\n",
    
    "============================================\n",
    sep = ""
  )
  
  
  return(
    comparison
  )
}